### Solution 1: AWS Secrets Manager (Recommended for Production)

Create a new `config/secrets.js`:

```javascript
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName, useCache = true) {
    // Check cache first
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const data = await this.client.getSecretValue({ 
        SecretId: secretName 
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error('Failed to retrieve secret');
    }
  }

  async refreshCache() {
    this.cache.clear();
  }

  // For graceful degradation during AWS outages
  async getSecretWithFallback(secretName, fallbackEnvVar) {
    try {
      return await this.getSecret(secretName);
    } catch (error) {
      console.warn(`Failed to get secret from AWS, using fallback for ${secretName}`);
      if (process.env.NODE_ENV === 'development' && process.env[fallbackEnvVar]) {
        return process.env[fallbackEnvVar];
      }
      throw error;
    }
  }
}

module.exports = new SecretsManager();
```

### Solution 2: HashiCorp Vault (Enterprise-Grade)

Create `config/vault.js`:

```javascript
const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN
    });
    this.cache = new Map();
    this.leaseDurations = new Map();
  }

  async getSecret(path) {
    try {
      // Check if we need to renew the lease
      if (this.cache.has(path)) {
        const cached = this.cache.get(path);
        const leaseDuration = this.leaseDurations.get(path);

        if (Date.now() - cached.timestamp < leaseDuration * 1000) {
          return cached.value;
        }
      }

      const result = await this.client.read(path);

      // Cache with lease information
      this.cache.set(path, {
        value: result.data,
        timestamp: Date.now()
      });

      this.leaseDurations.set(path, result.lease_duration || 3600);

      return result.data;
    } catch (error) {
      console.error(`Error retrieving secret from Vault at ${path}:`, error);
      throw new Error('Failed to retrieve secret from Vault');
    }
  }

  async renewLease(leaseId) {
    try {
      await this.client.renew({ lease_id: leaseId });
    } catch (error) {
      console.error('Failed to renew lease:', error);
    }
  }
}

module.exports = new VaultSecretsManager();
```

### Solution 3: Azure Key Vault

