const { DefaultAzureCredential } = require('@azure/identity');
const { SecretClient } = require('@azure/keyvault-secrets');

class AzureKeyVaultManager {
  constructor() {
    const vaultName = process.env.AZURE_KEYVAULT_NAME;
    if (!vaultName) {
      throw new Error('AZURE_KEYVAULT_NAME environment variable is required');
    }

    const vaultUrl = `https://${vaultName}.vault.azure.net`;
    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(vaultUrl, credential);
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache
    if (this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const secret = await this.client.getSecret(secretName);

      this.cache.set(secretName, {
        value: secret.value,
        timestamp: Date.now()
      });

      return secret.value;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName} from Azure Key Vault:`, error);
      throw new Error('Failed to retrieve secret from Azure Key Vault');
    }
  }
}

module.exports = new AzureKeyVaultManager();
```

