// config/vault.js
const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN, // In production, use AppRole or Kubernetes auth
    });
    this.mountPoint = process.env.VAULT_MOUNT_POINT || 'secret';
  }

  async getSecret(path) {
    try {
      const result = await this.client.read(`${this.mountPoint}/data/${path}`);
      return result.data.data;
    } catch (error) {
      console.error(`Error reading secret from Vault: ${path}`, error);
      throw new Error(`Failed to retrieve secret from Vault: ${path}`);
    }
  }

  async getDatabaseConfig() {
    const secrets = await this.getSecret('app/database');
    return {
      host: secrets.host,
      port: secrets.port,
      database: secrets.database,
      user: secrets.username,
      password: secrets.password,
      ssl: {
        rejectUnauthorized: true,
        ca: secrets.ca_cert
      }
    };
  }

  async rotateSecret(path, newValue) {
    try {
      await this.client.write(`${this.mountPoint}/data/${path}`, {
        data: newValue
      });
      console.log(`Secret rotated successfully: ${path}`);
    } catch (error) {
      console.error(`Error rotating secret: ${path}`, error);
      throw error;
    }
  }

  // Lease management for dynamic secrets
  async renewLease(leaseId) {
    try {
      await this.client.renew({ lease_id: leaseId });
    } catch (error) {
      console.error('Error renewing lease:', error);
      throw error;
    }
  }
}

