// config/azure-secrets.js
const { SecretClient } = require('@azure/keyvault-secrets');
const { DefaultAzureCredential } = require('@azure/identity');

class AzureSecretsManager {
  constructor() {
    const vaultName = process.env.AZURE_VAULT_NAME;
    const vaultUrl = `https://${vaultName}.vault.azure.net`;

    this.client = new SecretClient(vaultUrl, new DefaultAzureCredential());
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const secret = await this.client.getSecret(secretName);

      // Cache the secret
      this.cache.set(secretName, {
        value: secret.value,
        timestamp: Date.now()
      });

      return secret.value;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getDatabaseUrl() {
    return await this.getSecret('database-url');
  }

  async getAPIKey(service) {
    return await this.getSecret(`${service}-api-key`);
  }
}

