const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Retrieve secret from AWS Secrets Manager with caching
   * @param {string} secretName - Name of the secret in AWS
   * @returns {Promise<object>} - Parsed secret value
   */
  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
      });

      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secret = buff.toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now(),
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  /**
   * Initialize all application secrets
   * @returns {Promise<object>} - All secrets
   */
  async initializeSecrets() {
    const secretName = process.env.SECRET_NAME || 'app/production/secrets';

    try {
      const secrets = await this.getSecret(secretName);

      // Validate required secrets
      const requiredSecrets = [
        'DATABASE_URL',
        'JWT_SECRET',
        'AWS_ACCESS_KEY_ID',
        'AWS_SECRET_ACCESS_KEY',
      ];

      const missing = requiredSecrets.filter(key => !secrets[key]);
      if (missing.length > 0) {
        throw new Error(`Missing required secrets: ${missing.join(', ')}`);
      }

      return secrets;
    } catch (error) {
      console.error('Failed to initialize secrets:', error.message);
      throw error;
    }
  }

  /**
   * Rotate secret (trigger rotation in AWS)
   * @param {string} secretName - Name of secret to rotate
   */
  async rotateSecret(secretName) {
    // Clear cache to force refresh
    this.cache.delete(secretName);

    // In production, trigger AWS rotation
    // This would call AWS Secrets Manager rotation APIs
    console.log(`Secret rotation triggered for: ${secretName}`);
  }

  /**
   * Clear all cached secrets (security measure)
   */
  clearCache() {
    this.cache.clear();
  }
}

