      ? 'Internal server error'
      : err.message
  });
});

// ============================================
// SERVER STARTUP WITH SECRETS INITIALIZATION
// ============================================

async function startServer() {
  try {
    // CRITICAL: Load secrets BEFORE starting server
    await initializeApp();

    const PORT = process.env.PORT || 3000;
    const server = app.listen(PORT, () => {
      logger.info(`Server running on port ${PORT}`);
      logger.info(`Environment: ${process.env.NODE_ENV || 'development'}`);
      logger.info('✓ Secrets loaded from AWS Secrets Manager');
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM received, shutting down gracefully');

      // Clear secrets from memory
      secrets = null;
      getSecretsManager().clearCache();

      server.close(() => {
        logger.info('Server closed');
        process.exit(0);
      });
    });

    return server;
  } catch (error) {
    logger.error('Failed to start server', { error: error.message });
    process.exit(1);
  }
}

// Start server if this file is run directly
if (require.main === module) {
  startServer();
}

module.exports = { app, initializeApp, startServer };

