// Secure application with comprehensive security measures
// Addresses OWASP Top 10 vulnerabilities

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// =============================================================================
// SECURITY MIDDLEWARE
// =============================================================================

// 1. Security Headers (protects against XSS, clickjacking, etc.)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// 2. CORS Configuration (whitelist specific origins)
const corsOptions = {
  origin: function (origin, callback) {
    const whitelist = [
      'https://yourdomain.com',
      'https://app.yourdomain.com'
    ];

    // Allow requests with no origin (mobile apps, Postman, etc.)
    if (!origin || whitelist.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));

// 3. Request Size Limits (prevent DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Rate Limiting (prevent brute force and DoS)
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // stricter limit for sensitive endpoints
  message: 'Too many requests, please try again later.',
});

app.use('/api/', generalLimiter);

// 5. Logging (security monitoring)
app.use(morgan('combined'));

// =============================================================================
// AUTHENTICATION MIDDLEWARE
// =============================================================================

// Simple API key authentication (replace with JWT, OAuth2, etc. in production)
const authenticateAPIKey = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'API key is required'
    });
  }

  // In production, validate against a secure store (database, secrets manager)
  const validAPIKeys = process.env.VALID_API_KEYS?.split(',') || [];

  if (!validAPIKeys.includes(apiKey)) {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Invalid API key'
    });
  }

  next();
};

// JWT Authentication Example (more secure)
const jwt = require('jsonwebtoken');

const authenticateJWT = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication token required'
    });
  }

  const token = authHeader.substring(7);

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET || 'change-this-secret');
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Invalid or expired token'
    });
  }
};

// =============================================================================
// INPUT VALIDATION MIDDLEWARE
// =============================================================================

const validateUserId = [
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
];

// Middleware to check validation results
const checkValidation = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation Error',
      details: errors.array()
    });
  }
  next();
};

// =============================================================================
// ROUTES
// =============================================================================

// Public health check endpoint (no authentication needed)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Protected users endpoint with authentication and input validation
app.get('/api/users',
  authenticateJWT, // or authenticateAPIKey
  validateUserId,
  checkValidation,
  (req, res) => {
    try {
      // Sanitize output - don't expose sensitive data
      const users = [
        { id: 1, name: 'Alice', email: 'a***e@example.com' },
        { id: 2, name: 'Bob', email: 'b**@example.com' },
      ];

      // Apply filters if provided
      let filteredUsers = users;

      if (req.query.id) {
        filteredUsers = users.filter(u => u.id === req.query.id);
      }

      // Pagination
      const limit = req.query.limit || 10;
      const offset = req.query.offset || 0;
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          limit: limit,
          offset: offset
        }
      });
    } catch (error) {
      // Don't expose internal error details
      console.error('Error fetching users:', error);
      res.status(500).json({
        error: 'Internal Server Error',
        message: 'An error occurred while processing your request'
      });
    }
  }
);

// =============================================================================
// ERROR HANDLING
// =============================================================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist'
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  // Log error for monitoring
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't expose internal errors in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'An unexpected error occurred'
    : err.message;

  res.status(statusCode).json({
    error: 'Error',
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// =============================================================================
// SERVER CONFIGURATION
// =============================================================================

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown();
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown();
});

module.exports = app;

# Security Review Report for app.js

**Date:** 2024
**Severity Levels:** 🔴 CRITICAL | 🟠 HIGH | 🟡 MEDIUM | 🟢 LOW

---

## Executive Summary

The current `app.js` implementation has **10 significant security vulnerabilities** that expose the application to OWASP Top 10 risks. The most critical issues include:

1. No authentication/authorization
2. Missing security headers
3. No rate limiting
4. Information disclosure
5. No input validation

**Recommendation:** Implement the secure version (`app.secure.js`) immediately.

---

## Detailed Findings

### 🔴 1. Broken Authentication (OWASP A07:2021)

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Issue:** No authentication mechanism. Anyone can access user data.

**Attack Scenario:**
```bash
# Attacker can freely access sensitive data
curl http://your-server:3000/users
# Returns all user emails without any credentials
```

**Fix:**
```javascript
const authenticateJWT = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.substring(7);

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};

// Apply to protected routes
app.get('/api/users', authenticateJWT, (req, res) => {
  // ... user handling
});
```

---

### 🟠 2. Injection Vulnerabilities (OWASP A03:2021)

**Issue:** While the current code doesn't use a database, there's no input validation for query parameters. If this code evolves to use databases, it's vulnerable to SQL/NoSQL injection.

**Vulnerable Example (future risk):**
```javascript
// DON'T DO THIS
app.get('/users/:id', (req, res) => {
  const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
  // SQL Injection vulnerable!
});
```

**Attack Scenario:**
```bash
curl "http://your-server:3000/users/1%20OR%201=1"
# Could expose all users
```

**Fix:**
```javascript
const { param, validationResult } = require('express-validator');

app.get('/users/:id',
  param('id').isInt().toInt(), // Validate and sanitize
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Safe to use req.params.id now
    // Use parameterized queries for database
    const query = 'SELECT * FROM users WHERE id = ?';
    db.query(query, [req.params.id]);
  }
);
```

---

### 🟠 3. Security Misconfiguration (OWASP A05:2021)

**Issue:** Missing security headers expose the app to various attacks.

**Current Risk:**
- No XSS protection headers
- No clickjacking protection
- MIME-sniffing attacks possible
- Information leakage (Express headers exposed)

**Fix:**
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' }, // Prevent clickjacking
  noSniff: true, // Prevent MIME sniffing
  xssFilter: true, // XSS protection
}));

// Hide Express from headers
app.disable('x-powered-by');
```

---

### 🟠 4. Identification and Authentication Failures (OWASP A07:2021)

**Issue:** No rate limiting allows brute force attacks.

**Attack Scenario:**
```bash
# Attacker can hammer the endpoint
for i in {1..100000}; do
  curl http://your-server:3000/users &
done
# Server becomes unresponsive
```

**Fix:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply to all routes
app.use('/api/', limiter);

// Stricter limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
});

app.use('/api/login', strictLimiter);
```

---

### 🟡 5. Sensitive Data Exposure (OWASP A02:2021)

**Current Code:**
```javascript
res.json([
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
]);
```

**Issue:** Email addresses are PII (Personally Identifiable Information) exposed without authentication.

**Fix - Option 1: Mask sensitive data**
```javascript
const maskEmail = (email) => {
  const [local, domain] = email.split('@');
  const maskedLocal = local.charAt(0) + '***' + local.charAt(local.length - 1);
  return `${maskedLocal}@${domain}`;
};

res.json([
  { id: 1, name: 'Alice', email: maskEmail('alice@example.com') },
  { id: 2, name: 'Bob', email: maskEmail('bob@example.com') },
]);
// Returns: a***e@example.com
```

**Fix - Option 2: Role-based access**
```javascript
app.get('/api/users', authenticateJWT, (req, res) => {
  const users = getUsersFromDB();

  // Only return full details to admins
  const responseData = users.map(user => {
    if (req.user.role === 'admin') {
      return user; // Full data
    } else {
      return { id: user.id, name: user.name }; // Limited data
    }
  });

  res.json(responseData);
});
```

---

### 🟡 6. Missing CORS Policy (Security Misconfiguration)

**Issue:** No CORS configuration can lead to unintended cross-origin access.

**Fix:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: function (origin, callback) {
    const whitelist = [
      'https://yourdomain.com',
      'https://app.yourdomain.com'
    ];

    if (!origin || whitelist.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));
```

---

### 🟡 7. Insufficient Logging and Monitoring (OWASP A09:2021)

**Issue:** No logging means you can't detect or respond to attacks.

**Fix:**
```javascript
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Create a write stream for access logs
const accessLogStream = fs.createWriteStream(
  path.join(__dirname, 'logs', 'access.log'),
  { flags: 'a' }
);

// Log all requests
app.use(morgan('combined', { stream: accessLogStream }));

// Security event logging
const logSecurityEvent = (event, req, details) => {
  const logEntry = {
    timestamp: new Date().toISOString(),
    event: event,
    ip: req.ip,
    method: req.method,
    path: req.path,
    userAgent: req.get('user-agent'),
    details: details
  };

  console.warn('SECURITY EVENT:', JSON.stringify(logEntry));
  // Send to SIEM or security monitoring service
};

// Example usage
app.use((req, res, next) => {
  if (!req.headers.authorization) {
    logSecurityEvent('unauthorized_access_attempt', req, {
      endpoint: req.path
    });
  }
  next();
});
```

---

### 🟡 8. No Error Handling (Security Misconfiguration)

**Issue:** Unhandled errors can crash the app or leak sensitive information.

**Current Risk:**
```javascript
// If any error occurs, it could expose stack traces
app.get('/users', (req, res) => {
  const data = dangerousOperation(); // Could throw error
  res.json(data); // No error handling
});
```

**Fix:**
```javascript
// Route-level error handling
app.get('/api/users', async (req, res, next) => {
  try {
    const users = await fetchUsers();
    res.json(users);
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error details internally
  console.error({
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Send safe error response
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred'
      : err.message, // Only show details in development
  });
});
```

---

### 🟡 9. No Request Size Limits (DoS Vulnerability)

**Issue:** No limits on request body size enables DoS attacks.

**Attack Scenario:**
```javascript
// Attacker sends huge payload
fetch('http://your-server:3000/api/data', {
  method: 'POST',
  body: 'x'.repeat(1000000000) // 1GB of data
});
// Server runs out of memory
```

**Fix:**
```javascript
// Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// For file uploads
const multer = require('multer');
const upload = multer({
  limits: {
    fileSize: 5 * 1024 * 1024 // 5MB max file size
  }
});
```

---

### 🟢 10. No HTTPS Enforcement

**Issue:** Application doesn't enforce HTTPS, allowing man-in-the-middle attacks.

**Fix:**
```javascript
// Redirect HTTP to HTTPS
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, `https://${req.headers.host}${req.url}`);
  }
  next();
});

// Or use Helmet's HSTS
app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true
}));
```

---

## Additional Security Best Practices

### 1. Environment Variables

**Never hardcode secrets:**
```javascript
// ❌ BAD
const JWT_SECRET = 'my-secret-key';

// ✅ GOOD
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is required');
}
```

### 2. Dependency Security

```bash
# Audit dependencies regularly
npm audit

# Fix vulnerabilities
npm audit fix

# Use tools like Snyk
npm install -g snyk
snyk test
```

### 3. Content Security Policy

```javascript
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'nonce-{random}'"],
    styleSrc: ["'self'", "'nonce-{random}'"],
    imgSrc: ["'self'", "data:", "https:"],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'self'"],
    frameSrc: ["'none'"],
  },
}));
```

### 4. SQL Injection Prevention

```javascript
// ❌ BAD - String concatenation
const query = `SELECT * FROM users WHERE id = ${userId}`;

// ✅ GOOD - Parameterized queries
const query = 'SELECT * FROM users WHERE id = ?';
db.query(query, [userId]);

// ✅ GOOD - ORM with proper escaping
const user = await User.findByPk(userId);
```

### 5. XSS Prevention

```javascript
// Sanitize user input
const sanitizeHtml = require('sanitize-html');

app.post('/api/comments', (req, res) => {
  const clean = sanitizeHtml(req.body.comment, {
    allowedTags: ['b', 'i', 'em', 'strong'],
    allowedAttributes: {}
  });

  // Save clean content
  saveComment(clean);
});
```

---

## Implementation Checklist

- [ ] Install required security packages
- [ ] Implement authentication (JWT or API key)
- [ ] Add authorization middleware
- [ ] Configure Helmet for security headers
- [ ] Set up rate limiting
- [ ] Add input validation on all endpoints
- [ ] Implement error handling
- [ ] Configure CORS properly
- [ ] Add logging and monitoring
- [ ] Set request size limits
- [ ] Enforce HTTPS
- [ ] Mask sensitive data in responses
- [ ] Add security tests
- [ ] Set up dependency scanning
- [ ] Configure environment variables
- [ ] Document security procedures

---

## Testing Security

