## ✅ Input Validation Patterns

### Query Parameter Validation
```javascript
const { query, validationResult } = require('express-validator');

const validateQuery = [
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('email').optional().isEmail().normalizeEmail(),
];

const checkValidation = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

app.get('/api/users', validateQuery, checkValidation, (req, res) => {
  // Safe to use validated parameters
});
```

### Body Validation
```javascript
const { body } = require('express-validator');

const validateUserInput = [
  body('email').isEmail().normalizeEmail(),
  body('name').trim().isLength({ min: 2, max: 50 }).escape(),
  body('age').optional().isInt({ min: 0, max: 150 }),
];

app.post('/api/users', validateUserInput, checkValidation, (req, res) => {
  // Safe to use req.body
});
```

