# ADDITIONAL SECURITY FINDING: Secrets Management

## 🔴 CRITICAL VULNERABILITY: Inadequate Secrets Management

### Issue Identified
The current implementation in `app.secure.js` loads secrets directly from `.env` files using `process.env`, which has several critical security issues:

### Problems with .env Files

1. **No Encryption at Rest**
   - Secrets stored in plain text on disk
   - Vulnerable if filesystem is compromised
   - Easy to accidentally commit to version control

2. **No Access Control**
   - Any process on the server can read .env files
   - No audit trail of who accessed secrets
   - No rotation mechanism

3. **No Secret Rotation**
   - Secrets remain static unless manually updated
   - No automatic expiration
   - Difficult to rotate across multiple instances

4. **Code References Secrets Directly**
   ```javascript
   // CURRENT (INSECURE)
   const decoded = jwt.verify(token, process.env.JWT_SECRET || 'change-this-secret');
   const validAPIKeys = process.env.VALID_API_KEYS?.split(',') || [];
   ```

---

## ✅ SOLUTION: Use a Secrets Manager

### Recommended Secrets Managers

1. **AWS Secrets Manager** (AWS environments)
2. **HashiCorp Vault** (Multi-cloud, on-premise)
3. **Azure Key Vault** (Azure environments)
4. **Google Cloud Secret Manager** (GCP environments)
5. **Doppler** (Platform-agnostic SaaS)

---

## 🛡️ Secure Implementation Example

### Option 1: AWS Secrets Manager

```javascript
// secrets-manager.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error('Error fetching secret:', error);
      throw new Error('Failed to retrieve secret');
    }
  }

  // Force refresh (call after rotation)
  clearCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

module.exports = new SecretsManager();
```

### Option 2: HashiCorp Vault

```javascript
// vault-client.js
const vault = require('node-vault');

class VaultClient {
  constructor() {
    this.client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN // Initial token only
    });
  }

  async getSecret(path) {
    try {
      const result = await this.client.read(path);
      return result.data;
    } catch (error) {
      console.error('Vault error:', error);
      throw new Error('Failed to retrieve secret from Vault');
    }
  }

  async rotateToken() {
    // Implement token rotation logic
    const newToken = await this.client.tokenRenewSelf();
    return newToken;
  }
}

module.exports = new VaultClient();
```

---

## 🔄 Updated Application with Secrets Manager

```javascript
// app.secure-with-secrets-manager.js
const express = require('express');
const helmet = require('helmet');
const jwt = require('jsonwebtoken');
const secretsManager = require('./secrets-manager');

const app = express();

// Initialize secrets on startup
let appSecrets;

async function initializeSecrets() {
  try {
    // Load all secrets at startup
    appSecrets = await secretsManager.getSecret('app/production/secrets');

    // Validate required secrets exist
    const requiredSecrets = ['JWT_SECRET', 'VALID_API_KEYS'];
    for (const secret of requiredSecrets) {
      if (!appSecrets[secret]) {
        throw new Error(`Missing required secret: ${secret}`);
      }
    }

    console.log('✅ Secrets loaded successfully');
  } catch (error) {
    console.error('❌ Failed to load secrets:', error);
    process.exit(1); // Fail fast if secrets can't be loaded
  }
}

// JWT Authentication with Secrets Manager
const authenticateJWT = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication token required'
    });
  }

  const token = authHeader.substring(7);

  try {
    // Use secret from secrets manager (NOT process.env)
    const decoded = jwt.verify(token, appSecrets.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Invalid or expired token'
    });
  }
};

// API Key authentication with Secrets Manager
const authenticateAPIKey = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'API key is required'
    });
  }

  // Use secret from secrets manager
  const validAPIKeys = appSecrets.VALID_API_KEYS.split(',');

  if (!validAPIKeys.includes(apiKey)) {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Invalid API key'
    });
  }

  next();
};

// Health check that doesn't expose secret status
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

// Start server only after secrets are loaded
async function startServer() {
  await initializeSecrets();

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Secure server running on port ${PORT}`);
  });

  // Set up secret rotation check (every hour)
  setInterval(async () => {
    try {
      secretsManager.clearCache();
      await initializeSecrets();
      console.log('✅ Secrets refreshed');
    } catch (error) {
      console.error('❌ Secret refresh failed:', error);
    }
  }, 3600000); // 1 hour
}

startServer().catch(console.error);

module.exports = app;
```

