// Secure Express Application - Best Practices Implementation
// Addresses OWASP Top 10 vulnerabilities

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const cors = require('cors');
const morgan = require('morgan');
const winston = require('winston');

const app = express();

// ===================================
// 1. LOGGING & MONITORING
// ===================================
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.Console({ format: winston.format.simple() })
  ]
});

// HTTP request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// ===================================
// 2. SECURITY HEADERS (Helmet)
// ===================================
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// ===================================
// 3. CORS CONFIGURATION
// ===================================
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 600 // 10 minutes
};
app.use(cors(corsOptions));

// ===================================
// 4. RATE LIMITING
// ===================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      error: 'Too many requests',
      message: 'Please try again later'
    });
  }
});

// Apply to all routes
app.use(limiter);

// Stricter limit for authentication endpoints (when implemented)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later.'
});

// ===================================
// 5. BODY PARSING WITH SIZE LIMITS
// ===================================
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ===================================
// 6. DATA SANITIZATION
// ===================================
// Prevent NoSQL injection
app.use(mongoSanitize());

// Prevent XSS attacks
app.use(xss());

// Prevent HTTP Parameter Pollution
app.use(hpp());

// ===================================
// 7. CUSTOM SECURITY MIDDLEWARE
// ===================================

// Remove sensitive headers
app.use((req, res, next) => {
  res.removeHeader('X-Powered-By');
  next();
});

// Input validation middleware
const validateRequest = (schema) => {
  return (req, res, next) => {
    const { error } = schema.validate(req.query);
    if (error) {
      logger.warn(`Validation error: ${error.details[0].message}`);
      return res.status(400).json({
        error: 'Validation error',
        details: error.details[0].message
      });
    }
    next();
  };
};

// Authentication middleware (example - implement with JWT or sessions)
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    logger.warn(`Unauthorized access attempt to ${req.path} from IP: ${req.ip}`);
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication required'
    });
  }

  const token = authHeader.split(' ')[1];

  // TODO: Implement proper JWT verification
  // Example: jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {...})

  // For now, just check if token exists (REPLACE WITH REAL AUTH)
  if (!token || token === 'invalid') {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Invalid or expired token'
    });
  }

  // Attach user info to request (after real verification)
  req.user = { id: 1, role: 'user' }; // This should come from JWT payload
  next();
};

// Authorization middleware
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Authentication required'
      });
    }

    if (roles.length && !roles.includes(req.user.role)) {
      logger.warn(`Unauthorized access: User ${req.user.id} attempted to access ${req.path}`);
      return res.status(403).json({
        error: 'Forbidden',
        message: 'Insufficient permissions'
      });
    }

    next();
  };
};

// ===================================
// 8. ROUTES WITH SECURITY
// ===================================

// Public health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// Protected users endpoint with authentication
app.get('/users', authenticate, (req, res) => {
  try {
    // Don't expose email addresses to all authenticated users
    // Only return emails if user has admin role
    const isAdmin = req.user.role === 'admin';

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter sensitive data based on role
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      ...(isAdmin && { email: user.email }) // Only include email for admins
    }));

    logger.info(`User ${req.user.id} accessed users list`);

    res.json({
      success: true,
      data: sanitizedUsers
    });
  } catch (error) {
    logger.error(`Error in /users endpoint: ${error.message}`);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An error occurred while processing your request'
    });
  }
});

// ===================================
// 9. ERROR HANDLING
// ===================================

// 404 handler
app.use((req, res, next) => {
  logger.warn(`404 - Route not found: ${req.method} ${req.path}`);
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error(`Error: ${err.message}`, {
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ===================================
// 10. SECURE SERVER CONFIGURATION
// ===================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Secure server running on port ${PORT}`);
  logger.info(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  server.close(() => process.exit(1));
});

module.exports = app;

