/**
 * Secrets Management Abstraction Layer
 * 
 * Provides a unified interface for loading secrets from multiple sources:
 * - AWS Secrets Manager (production)
 * - HashiCorp Vault (production)
 * - Azure Key Vault (production)
 * - Google Cloud Secret Manager (production)
 * - Environment variables (development only)
 * 
 * Features:
 * - Automatic secret rotation
 * - Caching with TTL
 * - Audit logging
 * - Validation
 * - Fallback mechanisms
 */

const winston = require('winston');

// Initialize logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'secrets-audit.log' }),
    new winston.transports.Console()
  ]
});

class SecretsManager {
  constructor(options = {}) {
    this.provider = options.provider || process.env.SECRETS_PROVIDER || 'env';
    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 300000; // 5 minutes default
    this.required = options.required || [];
    this.providerInstance = null;

    this.initialize();
  }

  /**
   * Initialize the secrets provider
   */
  async initialize() {
    logger.info(`Initializing secrets manager with provider: ${this.provider}`);

    try {
      switch (this.provider) {
        case 'aws':
          const AWSSecretsProvider = require('./secrets-aws');
          this.providerInstance = new AWSSecretsProvider();
          break;

        case 'vault':
          const VaultSecretsProvider = require('./secrets-vault');
          this.providerInstance = new VaultSecretsProvider();
          break;

        case 'azure':
          const AzureSecretsProvider = require('./secrets-azure');
          this.providerInstance = new AzureSecretsProvider();
          break;

        case 'gcp':
          const GCPSecretsProvider = require('./secrets-gcp');
          this.providerInstance = new GCPSecretsProvider();
          break;

        case 'env':
          logger.warn('Using environment variables for secrets - NOT RECOMMENDED FOR PRODUCTION');
          const EnvSecretsProvider = require('./secrets-env');
          this.providerInstance = new EnvSecretsProvider();
          break;

        default:
          throw new Error(`Unknown secrets provider: ${this.provider}`);
      }

      await this.providerInstance.initialize();
      logger.info('Secrets manager initialized successfully');

      // Validate required secrets
      await this.validateRequiredSecrets();

    } catch (error) {
      logger.error('Failed to initialize secrets manager', { error: error.message });
      throw error;
    }
  }

  /**
   * Get a secret value
   * @param {string} key - Secret key
   * @param {object} options - Options (skipCache, version, etc.)
   * @returns {Promise<string>} Secret value
   */
  async getSecret(key, options = {}) {
    const startTime = Date.now();

    try {
      // Check cache first (unless skipCache is true)
      if (!options.skipCache) {
        const cached = this.getCached(key);
        if (cached) {
          logger.debug(`Secret retrieved from cache: ${key}`);
          this.auditLog('GET', key, 'SUCCESS', 'CACHE', Date.now() - startTime);
          return cached.value;
        }
      }

      // Fetch from provider
      const value = await this.providerInstance.getSecret(key, options);

      if (!value) {
        throw new Error(`Secret not found: ${key}`);
      }

      // Cache the value
      this.setCached(key, value);

      // Audit log
      this.auditLog('GET', key, 'SUCCESS', 'PROVIDER', Date.now() - startTime);

      return value;

    } catch (error) {
      logger.error(`Failed to get secret: ${key}`, { error: error.message });
      this.auditLog('GET', key, 'FAILED', 'PROVIDER', Date.now() - startTime, error.message);
      throw error;
    }
  }

  /**
   * Get multiple secrets at once
   * @param {Array<string>} keys - Array of secret keys
   * @returns {Promise<Object>} Object with key-value pairs
   */
  async getSecrets(keys) {
    const secrets = {};
    const promises = keys.map(async (key) => {
      try {
        secrets[key] = await this.getSecret(key);
      } catch (error) {
        logger.error(`Failed to load secret ${key}:`, error.message);
        throw error;
      }
    });

    await Promise.all(promises);
    return secrets;
  }

  /**
   * Refresh a secret (force reload from provider)
   * @param {string} key - Secret key
   */
  async refreshSecret(key) {
    logger.info(`Refreshing secret: ${key}`);
    this.cache.delete(key);
    return await this.getSecret(key, { skipCache: true });
  }

  /**
   * Refresh all cached secrets
   */
  async refreshAll() {
    logger.info('Refreshing all secrets');
    const keys = Array.from(this.cache.keys());
    this.cache.clear();

    const promises = keys.map(key => this.getSecret(key));
    await Promise.all(promises);

    logger.info('All secrets refreshed');
  }

  /**
   * Set a secret (if provider supports it)
   * @param {string} key - Secret key
   * @param {string} value - Secret value
   */
  async setSecret(key, value) {
    const startTime = Date.now();

    try {
      if (!this.providerInstance.setSecret) {
        throw new Error('Provider does not support setting secrets');
      }

      await this.providerInstance.setSecret(key, value);
      this.cache.delete(key); // Invalidate cache

      this.auditLog('SET', key, 'SUCCESS', 'PROVIDER', Date.now() - startTime);
      logger.info(`Secret set: ${key}`);

    } catch (error) {
      logger.error(`Failed to set secret: ${key}`, { error: error.message });
      this.auditLog('SET', key, 'FAILED', 'PROVIDER', Date.now() - startTime, error.message);
      throw error;
    }
  }

  /**
   * Rotate a secret (generate new value and update)
   * @param {string} key - Secret key
   * @param {Function} generator - Function to generate new secret value
   */
  async rotateSecret(key, generator) {
    const startTime = Date.now();

    try {
      if (!this.providerInstance.rotateSecret) {
        logger.warn(`Provider does not support rotation, falling back to manual set`);
        const newValue = await generator();
        await this.setSecret(key, newValue);
        return newValue;
      }

      const newValue = await this.providerInstance.rotateSecret(key, generator);
      this.cache.delete(key); // Invalidate cache

      this.auditLog('ROTATE', key, 'SUCCESS', 'PROVIDER', Date.now() - startTime);
      logger.info(`Secret rotated: ${key}`);

      return newValue;

    } catch (error) {
      logger.error(`Failed to rotate secret: ${key}`, { error: error.message });
      this.auditLog('ROTATE', key, 'FAILED', 'PROVIDER', Date.now() - startTime, error.message);
      throw error;
    }
  }

  /**
   * Validate that all required secrets are available
   */
  async validateRequiredSecrets() {
    if (this.required.length === 0) {
      return;
    }

    logger.info('Validating required secrets...');

    const missing = [];
    for (const key of this.required) {
      try {
        await this.getSecret(key);
      } catch (error) {
        missing.push(key);
      }
    }

    if (missing.length > 0) {
      const error = new Error(`Missing required secrets: ${missing.join(', ')}`);
      logger.error(error.message);
      throw error;
    }

    logger.info('All required secrets validated successfully');
  }

  /**
   * Get cached secret
   * @private
   */
  getCached(key) {
    const cached = this.cache.get(key);
    if (!cached) return null;

    const now = Date.now();
    if (now - cached.timestamp > this.cacheTTL) {
      this.cache.delete(key);
      return null;
    }

    return cached;
  }

  /**
   * Set cached secret
   * @private
   */
  setCached(key, value) {
    this.cache.set(key, {
      value,
      timestamp: Date.now()
    });
  }

  /**
   * Audit log for secret operations
   * @private
   */
  auditLog(operation, key, status, source, duration, error = null) {
    const logEntry = {
      timestamp: new Date().toISOString(),
      operation,
      secretKey: key,
      status,
      source,
      duration: `${duration}ms`,
      provider: this.provider,
      ...(error && { error })
    };

    logger.info('Secret operation', logEntry);
  }

  /**
   * Clear all cached secrets
   */
  clearCache() {
    logger.info('Clearing secrets cache');
    this.cache.clear();
  }

  /**
   * Get cache statistics
   */
  getCacheStats() {
    return {
      size: this.cache.size,
      keys: Array.from(this.cache.keys()),
      provider: this.provider
    };
  }

  /**
   * Health check for secrets manager
   */
  async healthCheck() {
    try {
      if (this.providerInstance.healthCheck) {
        await this.providerInstance.healthCheck();
      }
      return { status: 'healthy', provider: this.provider };
    } catch (error) {
      return { 
        status: 'unhealthy', 
        provider: this.provider, 
        error: error.message 
      };
    }
  }

  /**
   * Graceful shutdown
   */
  async shutdown() {
    logger.info('Shutting down secrets manager');
    this.clearCache();

    if (this.providerInstance.shutdown) {
      await this.providerInstance.shutdown();
    }
  }
}

// Singleton instance
let secretsManagerInstance = null;

/**
 * Initialize the global secrets manager
