/**
 * AWS Secrets Manager Provider
 * 
 * Integrates with AWS Secrets Manager for production secret storage
 * 
 * Features:
 * - Automatic secret rotation
 * - Version support
 * - Multi-region support
 * - IAM-based access control
 */

const { 
  SecretsManagerClient, 
  GetSecretValueCommand,
  PutSecretValueCommand,
  RotateSecretCommand,
  DescribeSecretCommand 
} = require('@aws-sdk/client-secrets-manager');

class AWSSecretsProvider {
  constructor(options = {}) {
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.prefix = options.prefix || process.env.SECRETS_PREFIX || '';
    this.client = null;
  }

  /**
   * Initialize AWS Secrets Manager client
   */
  async initialize() {
    this.client = new SecretsManagerClient({
      region: this.region
    });

    console.log(`AWS Secrets Manager initialized (region: ${this.region})`);
  }

  /**
   * Get secret from AWS Secrets Manager
   * @param {string} key - Secret key
   * @param {object} options - Options (version, versionStage)
   */
  async getSecret(key, options = {}) {
    const secretName = this.prefix ? `${this.prefix}/${key}` : key;

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionId: options.version,
        VersionStage: options.versionStage || 'AWSCURRENT'
      });

      const response = await this.client.send(command);

      // Return string or parse JSON
      if (response.SecretString) {
        try {
          const parsed = JSON.parse(response.SecretString);
          // If it's a JSON object with a single key matching the secret name, return that value
          if (typeof parsed === 'object' && parsed[key]) {
            return parsed[key];
          }
          // Otherwise return the whole parsed object (for complex secrets)
          return typeof parsed === 'object' ? parsed : response.SecretString;
        } catch {
          return response.SecretString;
        }
      }

      // Binary secrets
      if (response.SecretBinary) {
        return Buffer.from(response.SecretBinary).toString('utf8');
      }

      throw new Error('Secret has no value');

    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw new Error(`Failed to get secret ${secretName}: ${error.message}`);
    }
  }

  /**
   * Set/update a secret
   * @param {string} key - Secret key
   * @param {string|object} value - Secret value
   */
  async setSecret(key, value) {
    const secretName = this.prefix ? `${this.prefix}/${key}` : key;

    try {
      const secretString = typeof value === 'object' 
        ? JSON.stringify(value) 
        : String(value);

      const command = new PutSecretValueCommand({
        SecretId: secretName,
        SecretString: secretString
      });

      await this.client.send(command);

    } catch (error) {
      throw new Error(`Failed to set secret ${secretName}: ${error.message}`);
    }
  }

  /**
   * Rotate a secret
   * @param {string} key - Secret key
   * @param {Function} generator - Function to generate new secret
   */
  async rotateSecret(key, generator) {
    const secretName = this.prefix ? `${this.prefix}/${key}` : key;

    try {
      // Generate new value
      const newValue = await generator();

      // Use AWS rotation if Lambda function is configured
      // Otherwise, just update the secret
      const command = new RotateSecretCommand({
        SecretId: secretName,
        ClientRequestToken: `rotate-${Date.now()}`
      });

      try {
        await this.client.send(command);
      } catch (rotateError) {
        // If rotation Lambda not configured, fall back to manual update
        if (rotateError.name === 'InvalidRequestException') {
          await this.setSecret(key, newValue);
        } else {
          throw rotateError;
        }
      }

      return newValue;

    } catch (error) {
      throw new Error(`Failed to rotate secret ${secretName}: ${error.message}`);
    }
  }

  /**
   * Get secret metadata
   * @param {string} key - Secret key
   */
  async getSecretMetadata(key) {
    const secretName = this.prefix ? `${this.prefix}/${key}` : key;

    try {
      const command = new DescribeSecretCommand({
        SecretId: secretName
      });

      const response = await this.client.send(command);

      return {
        name: response.Name,
        arn: response.ARN,
        description: response.Description,
        rotationEnabled: response.RotationEnabled,
        lastRotated: response.LastRotatedDate,
        lastChanged: response.LastChangedDate,
        lastAccessed: response.LastAccessedDate,
        versionIds: response.VersionIdsToStages
      };

    } catch (error) {
      throw new Error(`Failed to get metadata for ${secretName}: ${error.message}`);
    }
  }

  /**
   * Health check
   */
  async healthCheck() {
    try {
      // Try to list one secret to verify connectivity
      const command = new GetSecretValueCommand({
        SecretId: `${this.prefix}/healthcheck`
      });

      await this.client.send(command);
      return true;
    } catch (error) {
      // ResourceNotFoundException is fine - means we can connect
      if (error.name === 'ResourceNotFoundException') {
        return true;
      }
      throw error;
    }
  }

  /**
   * Shutdown
   */
  async shutdown() {
    if (this.client) {
      this.client.destroy();
    }
  }
}

module.exports = AWSSecretsProvider;

/**
 * HashiCorp Vault Provider
 * 
 * Integrates with HashiCorp Vault for production secret storage
 * 
 * Features:
 * - Dynamic secrets
 * - Secret rotation
 * - Multiple authentication methods
 * - Audit logging
 */

const axios = require('axios');
const fs = require('fs').promises;

class VaultSecretsProvider {
  constructor(options = {}) {
    this.vaultAddr = options.vaultAddr || process.env.VAULT_ADDR || 'http://127.0.0.1:8200';
    this.vaultToken = options.vaultToken || process.env.VAULT_TOKEN;
    this.vaultNamespace = options.namespace || process.env.VAULT_NAMESPACE;
    this.mountPath = options.mountPath || process.env.VAULT_MOUNT_PATH || 'secret';
    this.authMethod = options.authMethod || process.env.VAULT_AUTH_METHOD || 'token';
    this.client = null;
  }

  /**
   * Initialize Vault client
   */
  async initialize() {
    // Create axios instance with base configuration
    this.client = axios.create({
      baseURL: this.vaultAddr,
      headers: {
        'Content-Type': 'application/json',
        ...(this.vaultNamespace && { 'X-Vault-Namespace': this.vaultNamespace })
      }
    });

    // Authenticate based on method
    await this.authenticate();

    console.log(`HashiCorp Vault initialized (addr: ${this.vaultAddr})`);
  }

  /**
   * Authenticate with Vault
   */
  async authenticate() {
    switch (this.authMethod) {
      case 'token':
        await this.authenticateToken();
        break;
      case 'kubernetes':
        await this.authenticateKubernetes();
        break;
      case 'approle':
        await this.authenticateAppRole();
        break;
      case 'aws':
        await this.authenticateAWS();
        break;
      default:
        throw new Error(`Unknown auth method: ${this.authMethod}`);
    }
  }

  /**
   * Token authentication
   */
  async authenticateToken() {
    if (!this.vaultToken) {
      throw new Error('VAULT_TOKEN not provided');
    }

    this.client.defaults.headers['X-Vault-Token'] = this.vaultToken;

    // Verify token
    try {
      await this.client.get('/v1/auth/token/lookup-self');
    } catch (error) {
      throw new Error('Invalid Vault token');
    }
  }

  /**
   * Kubernetes authentication
   */
  async authenticateKubernetes() {
    try {
      const role = process.env.VAULT_K8S_ROLE;
      const jwtPath = process.env.VAULT_K8S_JWT_PATH || '/var/run/secrets/kubernetes.io/serviceaccount/token';

      if (!role) {
        throw new Error('VAULT_K8S_ROLE not provided');
      }

      const jwt = await fs.readFile(jwtPath, 'utf8');

      const response = await this.client.post('/v1/auth/kubernetes/login', {
        role,
        jwt
      });

      this.vaultToken = response.data.auth.client_token;
      this.client.defaults.headers['X-Vault-Token'] = this.vaultToken;

    } catch (error) {
      throw new Error(`Kubernetes auth failed: ${error.message}`);
    }
  }

  /**
   * AppRole authentication
   */
  async authenticateAppRole() {
    try {
      const roleId = process.env.VAULT_ROLE_ID;
      const secretId = process.env.VAULT_SECRET_ID;

      if (!roleId || !secretId) {
        throw new Error('VAULT_ROLE_ID and VAULT_SECRET_ID required');
      }

      const response = await this.client.post('/v1/auth/approle/login', {
        role_id: roleId,
        secret_id: secretId
      });

      this.vaultToken = response.data.auth.client_token;
      this.client.defaults.headers['X-Vault-Token'] = this.vaultToken;

    } catch (error) {
      throw new Error(`AppRole auth failed: ${error.message}`);
    }
  }

  /**
   * AWS IAM authentication
   */
  async authenticateAWS() {
    try {
      const role = process.env.VAULT_AWS_ROLE;

      if (!role) {
        throw new Error('VAULT_AWS_ROLE not provided');
      }

      // This requires AWS SDK to generate signed request
      // Implementation depends on specific AWS auth requirements
      throw new Error('AWS auth not yet implemented');

    } catch (error) {
      throw new Error(`AWS auth failed: ${error.message}`);
    }
  }

  /**
   * Get secret from Vault
   * @param {string} key - Secret key
   * @param {object} options - Options (version)
   */
  async getSecret(key, options = {}) {
    try {
      // Determine if using KV v1 or v2
      const isKVv2 = await this.isKVv2();
      const path = isKVv2 
        ? `/v1/${this.mountPath}/data/${key}`
        : `/v1/${this.mountPath}/${key}`;

      const params = options.version && isKVv2 
        ? { version: options.version }
        : {};

      const response = await this.client.get(path, { params });

      // KV v2 wraps data in data.data
      const secretData = isKVv2 
        ? response.data.data.data 
        : response.data.data;

      // If single value secret, return the value directly
      if (secretData && Object.keys(secretData).length === 1) {
        return Object.values(secretData)[0];
      }

      return secretData;

    } catch (error) {
      if (error.response && error.response.status === 404) {
        throw new Error(`Secret not found: ${key}`);
      }
      throw new Error(`Failed to get secret ${key}: ${error.message}`);
    }
  }

  /**
   * Set/update a secret
   * @param {string} key - Secret key
   * @param {string|object} value - Secret value
   */
  async setSecret(key, value) {
    try {
      const isKVv2 = await this.isKVv2();
      const path = isKVv2 
        ? `/v1/${this.mountPath}/data/${key}`
        : `/v1/${this.mountPath}/${key}`;

      const data = typeof value === 'object' 
        ? value 
        : { value };

      const payload = isKVv2 
        ? { data }
        : data;

      await this.client.post(path, payload);

    } catch (error) {
      throw new Error(`Failed to set secret ${key}: ${error.message}`);
    }
  }

  /**
   * Delete a secret
   * @param {string} key - Secret key
   */
  async deleteSecret(key) {
    try {
      const isKVv2 = await this.isKVv2();
      const path = isKVv2 
        ? `/v1/${this.mountPath}/data/${key}`
        : `/v1/${this.mountPath}/${key}`;

      await this.client.delete(path);

    } catch (error) {
      throw new Error(`Failed to delete secret ${key}: ${error.message}`);
    }
  }

  /**
   * Rotate a secret
   * @param {string} key - Secret key
   * @param {Function} generator - Function to generate new secret
   */
  async rotateSecret(key, generator) {
    try {
      const newValue = await generator();
      await this.setSecret(key, newValue);
      return newValue;
    } catch (error) {
      throw new Error(`Failed to rotate secret ${key}: ${error.message}`);
    }
  }

  /**
   * List secrets
   * @param {string} path - Path to list
   */
  async listSecrets(path = '') {
    try {
      const isKVv2 = await this.isKVv2();
      const listPath = isKVv2 
        ? `/v1/${this.mountPath}/metadata/${path}`
        : `/v1/${this.mountPath}/${path}`;

      const response = await this.client({
        method: 'LIST',
        url: listPath
      });

      return response.data.data.keys || [];

    } catch (error) {
      if (error.response && error.response.status === 404) {
        return [];
      }
      throw new Error(`Failed to list secrets: ${error.message}`);
    }
  }

  /**
   * Check if using KV v2
   * @private
   */
  async isKVv2() {
    try {
      const response = await this.client.get(`/v1/sys/mounts/${this.mountPath}`);
      return response.data.data.options?.version === '2';
    } catch {
      return false; // Assume v1 if can't determine
    }
  }

  /**
   * Renew token
   */
  async renewToken() {
    try {
      const response = await this.client.post('/v1/auth/token/renew-self');
      this.vaultToken = response.data.auth.client_token;
      this.client.defaults.headers['X-Vault-Token'] = this.vaultToken;
    } catch (error) {
      throw new Error(`Failed to renew token: ${error.message}`);
    }
  }

  /**
   * Health check
   */
  async healthCheck() {
    try {
      const response = await this.client.get('/v1/sys/health');
      return response.status === 200;
    } catch (error) {
      // Vault returns 429 when sealed, 503 when not initialized
      if ([429, 503].includes(error.response?.status)) {
        throw new Error('Vault is sealed or not initialized');
      }
      throw error;
    }
  }

  /**
   * Shutdown
   */
  async shutdown() {
    // Revoke token on shutdown (optional)
    try {
      if (this.authMethod !== 'token') { // Don't revoke manually provided tokens
        await this.client.post('/v1/auth/token/revoke-self');
      }
    } catch (error) {
      console.error('Failed to revoke token on shutdown:', error.message);
    }
  }
}

module.exports = VaultSecretsProvider;

/**
 * Environment Variables Provider (Development Only)
 * 
 * Simple provider that loads secrets from environment variables
 * 
 * ⚠️ WARNING: NOT FOR PRODUCTION USE
 * Only use for local development and testing
 */

require('dotenv').config();

class EnvSecretsProvider {
  constructor() {
    this.secrets = new Map();
    console.warn('⚠️  WARNING: Using environment variables for secrets');
    console.warn('⚠️  This is NOT secure for production use');
  }

  /**
   * Initialize provider
   */
  async initialize() {
    // Load all env vars that look like secrets
    const secretPrefixes = ['SECRET_', 'KEY_', 'TOKEN_', 'PASSWORD_', 'API_KEY'];

    Object.keys(process.env).forEach(key => {
      const isSecret = secretPrefixes.some(prefix => key.startsWith(prefix)) ||
                      key.includes('SECRET') ||
                      key.includes('PASSWORD') ||
                      key.includes('TOKEN');

      if (isSecret) {
        this.secrets.set(key, process.env[key]);
      }
    });

    // Also support direct mapping
    this.secrets.set('JWT_SECRET', process.env.JWT_SECRET);
    this.secrets.set('SESSION_SECRET', process.env.SESSION_SECRET);
    this.secrets.set('DATABASE_URL', process.env.DATABASE_URL);
    this.secrets.set('REDIS_URL', process.env.REDIS_URL);
    this.secrets.set('API_KEY', process.env.API_KEY);
    this.secrets.set('SMTP_PASSWORD', process.env.SMTP_PASS);

    console.log(`Loaded ${this.secrets.size} secrets from environment`);
  }

  /**
   * Get secret value
   * @param {string} key - Secret key
   */
  async getSecret(key) {
    // Try exact match first
    let value = this.secrets.get(key) || process.env[key];

    // Try with common prefixes
    if (!value) {
      const prefixes = ['SECRET_', 'APP_', ''];
      for (const prefix of prefixes) {
        const fullKey = prefix + key;
        value = process.env[fullKey];
        if (value) break;
      }
    }

    if (!value) {
      throw new Error(`Secret not found: ${key}`);
    }

    return value;
  }

  /**
   * Set secret (updates process.env)
   * @param {string} key - Secret key
   * @param {string} value - Secret value
   */
  async setSecret(key, value) {
    process.env[key] = value;
    this.secrets.set(key, value);
  }

  /**
   * Rotate secret
   * @param {string} key - Secret key
   * @param {Function} generator - Function to generate new secret
   */
  async rotateSecret(key, generator) {
    const newValue = await generator();
    await this.setSecret(key, newValue);
    return newValue;
  }

  /**
   * Health check
   */
  async healthCheck() {
    return true;
  }

  /**
   * Shutdown
   */
  async shutdown() {
    // Nothing to clean up
  }
}

module.exports = EnvSecretsProvider;

