const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.Console({ format: winston.format.simple() })
  ]
});

// HTTP request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// ===================================
// 2. SECURITY HEADERS (Helmet)
// ===================================
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// ===================================
// 3. CORS CONFIGURATION
// ===================================
const corsOptions = {
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or Postman)
    if (!origin) return callback(null, true);

    if (config.allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn(`CORS blocked origin: ${origin}`);
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 600
};

app.use(cors(corsOptions));

// ===================================
// 4. RATE LIMITING
// ===================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      error: 'Too many requests',
      message: 'Please try again later'
    });
  }
});

app.use(limiter);

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later.'
});

// ===================================
// 5. BODY PARSING WITH SIZE LIMITS
// ===================================
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ===================================
// 6. DATA SANITIZATION
// ===================================
app.use(mongoSanitize());
app.use(xss());
app.use(hpp());

// ===================================
// 7. CUSTOM SECURITY MIDDLEWARE
// ===================================

app.use((req, res, next) => {
  res.removeHeader('X-Powered-By');
  next();
});

// Authentication middleware using secrets from secrets manager
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    logger.warn(`Unauthorized access attempt to ${req.path} from IP: ${req.ip}`);
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication required'
    });
  }

  const token = authHeader.split(' ')[1];

  try {
    // Verify JWT using secret from secrets manager
    const decoded = jwt.verify(token, config.jwtSecret, {
      algorithms: ['HS256'],
      issuer: 'secure-app',
      audience: 'api'
    });

    req.user = decoded;
    next();
  } catch (error) {
    logger.warn(`Invalid token from IP: ${req.ip}`, { error: error.message });
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Invalid or expired token'
    });
  }
};

// Authorization middleware
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Authentication required'
      });
    }

    if (roles.length && !roles.includes(req.user.role)) {
      logger.warn(`Unauthorized access: User ${req.user.id} attempted to access ${req.path}`);
      return res.status(403).json({
        error: 'Forbidden',
        message: 'Insufficient permissions'
      });
    }

    next();
  };
};

// ===================================
// 8. ROUTES WITH SECURITY
// ===================================

// Public health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// Secrets manager health check (admin only)
app.get('/health/secrets', authenticate, authorize('admin'), async (req, res) => {
  try {
    const health = await secretsManager.healthCheck();
    const stats = secretsManager.getCacheStats();

    res.json({
      success: true,
      secretsManager: health,
      cache: stats
    });
  } catch (error) {
    logger.error('Secrets health check failed', { error: error.message });
    res.status(500).json({
      success: false,
      error: 'Health check failed'
    });
  }
});

// Endpoint to refresh secrets (admin only)
app.post('/admin/secrets/refresh', authenticate, authorize('admin'), async (req, res) => {
  try {
    const { secretKey } = req.body;

    if (secretKey) {
      await secretsManager.refreshSecret(secretKey);
      logger.info(`Secret refreshed by user ${req.user.id}: ${secretKey}`);
    } else {
      await secretsManager.refreshAll();
      logger.info(`All secrets refreshed by user ${req.user.id}`);
    }

    res.json({
      success: true,
      message: secretKey ? `Secret ${secretKey} refreshed` : 'All secrets refreshed'
    });
  } catch (error) {
    logger.error('Secret refresh failed', { error: error.message });
    res.status(500).json({
      success: false,
      error: 'Failed to refresh secrets'
    });
  }
});

// Protected users endpoint with authentication
app.get('/users', authenticate, (req, res) => {
  try {
    const isAdmin = req.user.role === 'admin';

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      ...(isAdmin && { email: user.email })
    }));

    logger.info(`User ${req.user.id} accessed users list`);

    res.json({
      success: true,
      data: sanitizedUsers
    });
  } catch (error) {
    logger.error(`Error in /users endpoint: ${error.message}`);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An error occurred while processing your request'
    });
  }
});

// Login endpoint (example)
app.post('/auth/login', authLimiter, async (req, res) => {
  try {
    const { username, password } = req.body;

    // TODO: Validate credentials against database
    // For demo purposes only
    if (username === 'demo' && password === 'demo') {
      const token = jwt.sign(
        { 
          id: 1, 
          username: 'demo', 
          role: 'user' 
        },
        config.jwtSecret,
        { 
          expiresIn: '1h',
          issuer: 'secure-app',
          audience: 'api'
        }
      );

      logger.info(`User logged in: ${username}`);

      res.json({
        success: true,
        token
      });
    } else {
      logger.warn(`Failed login attempt for user: ${username} from IP: ${req.ip}`);
      res.status(401).json({
        success: false,
        error: 'Invalid credentials'
      });
    }
  } catch (error) {
    logger.error('Login error', { error: error.message });
    res.status(500).json({
      success: false,
      error: 'Login failed'
    });
  }
});

// ===================================
// 9. ERROR HANDLING
// ===================================

app.use((req, res, next) => {
  logger.warn(`404 - Route not found: ${req.method} ${req.path}`);
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist'
  });
});

app.use((err, req, res, next) => {
  logger.error(`Error: ${err.message}`, {
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  const isDevelopment = config.nodeEnv === 'development';

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ===================================
// 10. SECURE SERVER CONFIGURATION
// ===================================

async function startServer() {
  // Initialize secrets first
  await initializeApp();

  const server = app.listen(config.port, () => {
    logger.info(`Secure server running on port ${config.port}`);
    logger.info(`Environment: ${config.nodeEnv}`);
    logger.info(`Secrets provider: ${process.env.SECRETS_PROVIDER || 'env'}`);
  });

  // Graceful shutdown
  const shutdown = async (signal) => {
    logger.info(`${signal} signal received: closing HTTP server`);

    server.close(async () => {
      logger.info('HTTP server closed');

      // Shutdown secrets manager
      if (secretsManager) {
        await secretsManager.shutdown();
      }

      process.exit(0);
    });

    // Force close after 10 seconds
    setTimeout(() => {
      logger.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
    server.close(() => process.exit(1));
  });

  // Handle uncaught exceptions
  process.on('uncaughtException', (error) => {
    logger.error('Uncaught Exception:', error);
    server.close(() => process.exit(1));
  });

  return server;
}

// Start the server
if (require.main === module) {
  startServer().catch(error => {
    console.error('Failed to start server:', error);
    process.exit(1);
  });
}

module.exports = { app, startServer };

# Secrets Management Documentation

## Overview

This document describes the comprehensive secrets management solution that addresses the security vulnerability of loading secrets directly from `.env` files.

---

## 🔴 The Problem

### Original Implementation Issues:

```javascript
// ❌ INSECURE: Direct access to process.env
const JWT_SECRET = process.env.JWT_SECRET;
const DATABASE_URL = process.env.DATABASE_URL;

jwt.verify(token, process.env.JWT_SECRET, ...);
```

### Security Risks:

1. **Secrets in Plain Text** - `.env` files store unencrypted secrets
2. **No Rotation** - Secrets can't be rotated without application restart
3. **No Audit Trail** - Can't track secret access or changes
4. **Limited Access Control** - All secrets available to application process
5. **Secret Sprawl** - Multiple `.env` files across environments
6. **Git Exposure Risk** - Easy to accidentally commit `.env` files
7. **Container Issues** - Secrets visible in Docker images and process lists

---

## ✅ The Solution

### Architecture

```
┌─────────────────┐
│  Application    │
│  (app.js)       │
└────────┬────────┘
         │
         ↓
┌─────────────────┐
│ Secrets Manager │ ← Abstraction Layer
│ (config/secrets.js)
└────────┬────────┘
         │
    ┌────┴────┬─────────┬──────────┐
    ↓         ↓         ↓          ↓
┌─────┐  ┌─────┐  ┌──────┐  ┌──────┐
│ AWS │  │Vault│  │Azure │  │ .env │
│ SM  │  │     │  │  KV  │  │(dev) │
└─────┘  └─────┘  └──────┘  └──────┘
```

### Key Features

✅ **Provider Abstraction** - Single API for multiple secret stores  
✅ **Caching with TTL** - Reduces API calls, configurable expiration  
✅ **Audit Logging** - Complete trail of all secret operations  
✅ **Secret Rotation** - Automatic or manual secret rotation  
✅ **Validation** - Ensures required secrets are available at startup  
✅ **Fallback** - `.env` for local development, secure stores for production  
✅ **Health Checks** - Monitor secret store availability  

---

## 📁 Files Created

### 1. `config/secrets.js` (Abstraction Layer)

Main secrets manager with unified API:

```javascript
const { initializeSecretsManager, getSecretsManager } = require('./config/secrets');

// Initialize at startup
const secretsManager = await initializeSecretsManager({
  provider: 'aws', // or 'vault', 'azure', 'gcp', 'env'
  cacheTTL: 300000, // 5 minutes
  required: ['JWT_SECRET', 'DATABASE_URL']
});

// Get secrets
const jwtSecret = await secretsManager.getSecret('JWT_SECRET');
const allSecrets = await secretsManager.getSecrets(['JWT_SECRET', 'DB_URL']);

// Refresh secrets
await secretsManager.refreshSecret('JWT_SECRET');
await secretsManager.refreshAll();

// Rotate secrets
await secretsManager.rotateSecret('API_KEY', async () => {
  return generateNewApiKey();
});
```

**Features:**
- Provider-agnostic interface
- Caching with configurable TTL
- Batch secret loading
- Secret validation
- Audit logging
- Health checks

### 2. `config/secrets-aws.js` (AWS Secrets Manager)

Production-grade AWS integration:

```javascript
// Environment variables needed:
// AWS_REGION=us-east-1
// SECRETS_PREFIX=myapp/prod
// AWS credentials via IAM role or env vars

const AWSSecretsProvider = require('./config/secrets-aws');
const provider = new AWSSecretsProvider({
  region: 'us-east-1',
  prefix: 'myapp/prod'
});
```

**Features:**
- Automatic rotation support
- Version management
- Multi-region support
- IAM-based access control
- JSON and binary secrets

### 3. `config/secrets-vault.js` (HashiCorp Vault)

Multi-cloud Vault integration:

