// Secure Express Application - Production Ready
// Addresses OWASP Top 10 vulnerabilities

const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const mongoSanitize = require('express-mongo-sanitize'); // NoSQL injection prevention
const xss = require('xss-clean'); // XSS protection
const hpp = require('hpp'); // HTTP Parameter Pollution prevention
const cors = require('cors');
const morgan = require('morgan'); // Logging
const { body, query, validationResult } = require('express-validator');

const app = express();

// ===================================
// 1. SECURITY MIDDLEWARE
// ===================================

// Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: {
    action: 'deny' // Prevent clickjacking
  },
  noSniff: true, // Prevent MIME-type sniffing
  xssFilter: true,
}));

// CORS configuration - restrict to known origins
const corsOptions = {
  origin: function (origin, callback) {
    // Define whitelist of allowed origins
    const whitelist = [
      'https://yourdomain.com',
      'https://app.yourdomain.com'
    ];

    // Allow requests with no origin (mobile apps, Postman, etc.) in development
    if (!origin && process.env.NODE_ENV === 'development') {
      return callback(null, true);
    }

    if (whitelist.indexOf(origin) !== -1 || !origin) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));

// Body parser with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Prevent HTTP Parameter Pollution
app.use(hpp({
  whitelist: ['sort', 'filter'] // Parameters that can appear multiple times
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', limiter);

// Stricter rate limiting for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true,
  message: 'Too many authentication attempts, please try again later.'
});

// Request logging (use winston in production)
if (process.env.NODE_ENV === 'production') {
  app.use(morgan('combined')); // Apache-style logging
} else {
  app.use(morgan('dev'));
}

// ===================================
// 2. AUTHENTICATION MIDDLEWARE
// ===================================

// Simple JWT authentication middleware (use proper auth library in production)
const jwt = require('jsonwebtoken');
const JWT_SECRET = process.env.JWT_SECRET || 'change-this-secret-in-production';

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ 
      error: 'Authentication required',
      message: 'No token provided' 
    });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ 
        error: 'Invalid token',
        message: 'Token verification failed' 
      });
    }
    req.user = user;
    next();
  });
};

// Role-based access control middleware
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!roles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        message: 'You do not have access to this resource' 
      });
    }

    next();
  };
};

// ===================================
// 3. INPUT VALIDATION HELPERS
// ===================================

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ===================================
// 4. SECURE ROUTES
// ===================================

// Health check - public endpoint (with limited info)
app.get('/api/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString()
    // Don't expose: version, environment, dependencies, etc.
  });
});

// Users endpoint - PROTECTED with authentication and validation
app.get('/api/users', 
  authenticateToken,
  authorize('admin', 'user'), // Only admin and user roles can access
  [
    // Input validation for query parameters
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('search')
      .optional()
      .trim()
      .escape()
      .isLength({ max: 100 })
      .withMessage('Search term too long')
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      // Sanitize and validate query parameters
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;

      // Log access for security monitoring
      console.log(`[SECURITY] User ${req.user.id} accessed /api/users at ${new Date().toISOString()}`);

      // Mock data - in production, fetch from database with parameterized queries
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      ];

      // Filter sensitive data based on user role
      const sanitizedUsers = users.map(user => {
        const { email, ...publicData } = user;
        // Only return email if user is admin or requesting their own data
        if (req.user.role === 'admin' || req.user.id === user.id) {
          return user;
        }
        return publicData;
      });

      res.json({
        success: true,
        data: sanitizedUsers,
        pagination: {
          page,
          limit,
          total: users.length
        }
      });
    } catch (error) {
      // Don't expose internal errors
      console.error('[ERROR] /api/users:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: 'An error occurred while processing your request'
      });
    }
  }
);

// Example: User by ID endpoint with validation
app.get('/api/users/:id',
  authenticateToken,
  [
    query('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // Validate user can only access their own data unless admin
      if (req.user.role !== 'admin' && req.user.id !== userId) {
        return res.status(403).json({ 
          error: 'Access denied',
          message: 'You can only access your own user data' 
        });
      }

      // Mock data - use parameterized queries in production
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ 
          error: 'Not found',
          message: 'User not found' 
        });
      }

      res.json({
        success: true,
        data: user
      });
    } catch (error) {
      console.error('[ERROR] /api/users/:id:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: 'An error occurred while processing your request'
      });
    }
  }
);

// Example: Login endpoint (with rate limiting)
app.post('/api/auth/login',
  authLimiter,
  [
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email is required'),
    body('password')
      .isLength({ min: 8 })
      .withMessage('Password must be at least 8 characters')
  ],
  handleValidationErrors,
  async (req, res) => {
    try {
      const { email, password } = req.body;

      // Log authentication attempt
      console.log(`[SECURITY] Login attempt for ${email} from IP ${req.ip}`);

      // In production: 
      // 1. Fetch user from database using parameterized query
      // 2. Compare password using bcrypt.compare()
      // 3. Implement account lockout after failed attempts
      // 4. Use secure session management

      // Mock authentication (NEVER do this in production!)
      if (email === 'admin@example.com' && password === 'SecurePass123!') {
        const token = jwt.sign(
          { id: 1, email, role: 'admin' },
          JWT_SECRET,
          { expiresIn: '1h', algorithm: 'HS256' }
        );

        res.json({
          success: true,
          token,
          expiresIn: 3600
        });
      } else {
        // Use same error message for invalid email or password (prevent user enumeration)
        res.status(401).json({ 
          error: 'Authentication failed',
          message: 'Invalid credentials' 
        });
      }
    } catch (error) {
      console.error('[ERROR] /api/auth/login:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: 'An error occurred during authentication'
      });
    }
  }
);

// ===================================
// 5. ERROR HANDLING
// ===================================

// 404 handler - must be after all routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource was not found'
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error details for debugging (use proper logging service)
  console.error('[ERROR]', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal errors to clients
  res.status(err.status || 500).json({
    error: err.status === 500 ? 'Internal server error' : err.message,
    message: process.env.NODE_ENV === 'development' ? err.message : 'An unexpected error occurred'
  });
});

// ===================================
// 6. SECURE SERVER STARTUP
// ===================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
  console.log(`[INFO] Server running securely on ${HOST}:${PORT}`);
  console.log(`[INFO] Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`[SECURITY] Security headers: Enabled`);
  console.log(`[SECURITY] Rate limiting: Enabled`);
  console.log(`[SECURITY] CORS: Configured`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('[INFO] SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('[INFO] HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('[INFO] SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('[INFO] HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

