## 📝 Input Validation Examples

```javascript
const { body, query, param } = require('express-validator');

// Email
body('email')
  .trim()
  .isEmail()
  .normalizeEmail()

// Password
body('password')
  .isLength({ min: 8, max: 128 })
  .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])/)

// Username
body('username')
  .trim()
  .isLength({ min: 3, max: 30 })
  .matches(/^[a-zA-Z0-9_-]+$/)

// Integer ID
param('id')
  .isInt({ min: 1 })

// URL
body('website')
  .optional()
  .isURL({ protocols: ['https'] })

// Date
body('birthdate')
  .isISO8601()
  .toDate()

// Phone
body('phone')
  .optional()
  .isMobilePhone()

// Array
body('tags')
  .isArray({ min: 1, max: 5 })
  .custom((tags) => tags.every(t => typeof t === 'string'))
```

---

## 🛡️ Security Headers

```javascript
app.use(helmet({
  // Content Security Policy
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'", "api.yourdomain.com"],
      fontSrc: ["'self'", "fonts.gstatic.com"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    }
  },

  // HTTP Strict Transport Security
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },

  // Prevent clickjacking
  frameguard: {
    action: 'deny'
  },

  // Prevent MIME sniffing
  noSniff: true,

  // XSS filter
  xssFilter: true,

  // Referrer policy
  referrerPolicy: {
    policy: 'strict-origin-when-cross-origin'
  }
}));
```

