// Unified Secrets Management Layer
// Supports multiple secret providers with fallback strategy

const crypto = require('crypto');

/**
 * Secrets Manager
 * Abstracts secret retrieval from multiple sources
 * Priority: Secrets Manager > Vault > Environment > Config File
 */
class SecretsManager {
  constructor(options = {}) {
    this.provider = options.provider || 'env'; // 'aws', 'vault', 'azure', 'gcp', 'env'
    this.environment = options.environment || process.env.NODE_ENV || 'development';
    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 300000; // 5 minutes default
    this.auditLog = [];
    this.secretsLoaded = false;
  }

  /**
   * Initialize secrets manager
   */
  async init() {
    console.log(`[SECRETS] Initializing secrets manager (provider: ${this.provider}, env: ${this.environment})`);

    try {
      switch (this.provider) {
        case 'aws':
          this.client = await this._initAWS();
          break;
        case 'vault':
          this.client = await this._initVault();
          break;
        case 'azure':
          this.client = await this._initAzure();
          break;
        case 'gcp':
          this.client = await this._initGCP();
          break;
        case 'env':
        default:
          this.client = await this._initEnv();
          break;
      }

      this.secretsLoaded = true;
      console.log('[SECRETS] Secrets manager initialized successfully');
    } catch (error) {
      console.error('[SECRETS] Failed to initialize secrets manager:', error.message);
      throw new Error('Secrets manager initialization failed');
    }
  }

  /**
   * Get secret by key
   */
  async getSecret(key, options = {}) {
    if (!this.secretsLoaded) {
      throw new Error('Secrets manager not initialized. Call init() first.');
    }

    // Check cache first
    const cached = this._getFromCache(key);
    if (cached && !options.refresh) {
      this._audit('CACHE_HIT', key);
      return cached;
    }

    try {
      let value;

      switch (this.provider) {
        case 'aws':
          value = await this._getFromAWS(key);
          break;
        case 'vault':
          value = await this._getFromVault(key);
          break;
        case 'azure':
          value = await this._getFromAzure(key);
          break;
        case 'gcp':
          value = await this._getFromGCP(key);
          break;
        case 'env':
        default:
          value = await this._getFromEnv(key);
          break;
      }

      if (!value && options.required !== false) {
        throw new Error(`Required secret '${key}' not found`);
      }

      // Validate secret strength
      if (options.validate !== false) {
        this._validateSecret(key, value);
      }

      // Cache the secret
      this._addToCache(key, value);
      this._audit('SECRET_ACCESS', key);

      return value;
    } catch (error) {
      this._audit('SECRET_ACCESS_FAILED', key, error.message);
      throw error;
    }
  }

  /**
   * Get multiple secrets at once
   */
  async getSecrets(keys) {
    const secrets = {};
    for (const key of keys) {
      secrets[key] = await this.getSecret(key);
    }
    return secrets;
  }

  /**
   * Validate all required secrets are present
   */
  async validateSecrets() {
    console.log('[SECRETS] Validating required secrets...');

    const requiredSecrets = [
      { key: 'JWT_SECRET', minLength: 32 },
      { key: 'SESSION_SECRET', minLength: 32 },
      { key: 'DB_PASSWORD', minLength: 16 },
    ];

    const issues = [];

    for (const { key, minLength } of requiredSecrets) {
      try {
        const value = await this.getSecret(key, { validate: false });

        if (!value) {
          issues.push(`${key}: Missing`);
        } else if (value.length < minLength) {
          issues.push(`${key}: Too short (min: ${minLength}, got: ${value.length})`);
        } else if (this._isWeakSecret(value)) {
          issues.push(`${key}: Weak secret detected`);
        }
      } catch (error) {
        issues.push(`${key}: ${error.message}`);
      }
    }

    if (issues.length > 0) {
      console.error('[SECRETS] Validation failed:');
      issues.forEach(issue => console.error(`  - ${issue}`));
      throw new Error('Secret validation failed');
    }

    console.log('[SECRETS] All secrets validated successfully');
    return true;
  }

  /**
   * Rotate a secret (trigger rotation in secrets manager)
   */
  async rotateSecret(key) {
    console.log(`[SECRETS] Rotating secret: ${key}`);

    try {
      switch (this.provider) {
        case 'aws':
          await this._rotateAWS(key);
          break;
        case 'vault':
          await this._rotateVault(key);
          break;
        default:
          throw new Error(`Secret rotation not supported for provider: ${this.provider}`);
      }

      // Clear cache
      this.cache.delete(key);
      this._audit('SECRET_ROTATED', key);

      console.log(`[SECRETS] Secret rotated successfully: ${key}`);
    } catch (error) {
      console.error(`[SECRETS] Failed to rotate secret ${key}:`, error.message);
      throw error;
    }
  }

  /**
   * Get audit log
   */
  getAuditLog() {
    return this.auditLog;
  }

  /**
   * Clear sensitive data from memory
   */
  clearCache() {
    console.log('[SECRETS] Clearing secrets cache');
    this.cache.clear();
  }

  // ===================================
  // PRIVATE METHODS
  // ===================================

  async _initEnv() {
    // Load from .env file
    require('dotenv').config();
    console.log('[SECRETS] Loaded secrets from environment variables');
    return { type: 'env' };
  }

  async _initAWS() {
    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    console.log('[SECRETS] Connected to AWS Secrets Manager');
    return client;
  }

  async _initVault() {
    const vault = require('node-vault');
    const client = vault({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN
    });
    console.log('[SECRETS] Connected to HashiCorp Vault');
    return client;
  }

  async _initAzure() {
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const credential = new DefaultAzureCredential();
    const vaultName = process.env.AZURE_KEYVAULT_NAME;
    const url = `https://${vaultName}.vault.azure.net`;

    const client = new SecretClient(url, credential);
    console.log('[SECRETS] Connected to Azure Key Vault');
    return client;
  }

  async _initGCP() {
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
    const client = new SecretManagerServiceClient();
    console.log('[SECRETS] Connected to GCP Secret Manager');
    return client;
  }

  async _getFromEnv(key) {
    return process.env[key];
  }

  async _getFromAWS(key) {
    try {
      const data = await this.client.getSecretValue({ SecretId: key }).promise();
      return data.SecretString || data.SecretBinary;
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        return null;
      }
      throw error;
    }
  }

  async _getFromVault(key) {
    try {
      const path = `secret/data/${this.environment}/${key}`;
      const result = await this.client.read(path);
      return result.data.data.value;
    } catch (error) {
      if (error.response?.statusCode === 404) {
        return null;
      }
      throw error;
    }
  }

  async _getFromAzure(key) {
    try {
      const secret = await this.client.getSecret(key);
      return secret.value;
    } catch (error) {
      if (error.statusCode === 404) {
        return null;
      }
      throw error;
    }
  }

  async _getFromGCP(key) {
    try {
      const projectId = process.env.GCP_PROJECT_ID;
      const name = `projects/${projectId}/secrets/${key}/versions/latest`;
      const [version] = await this.client.accessSecretVersion({ name });
      return version.payload.data.toString('utf8');
    } catch (error) {
      if (error.code === 5) { // NOT_FOUND
        return null;
      }
      throw error;
    }
  }

  async _rotateAWS(key) {
    await this.client.rotateSecret({ SecretId: key }).promise();
  }

  async _rotateVault(key) {
    // Vault handles rotation via lease management
    const path = `secret/data/${this.environment}/${key}`;
    await this.client.delete(path);
  }

  _getFromCache(key) {
    const cached = this.cache.get(key);
    if (!cached) return null;

    const now = Date.now();
    if (now - cached.timestamp > this.cacheTTL) {
      this.cache.delete(key);
      return null;
    }

    return cached.value;
  }

  _addToCache(key, value) {
    this.cache.set(key, {
      value,
      timestamp: Date.now()
    });
  }

  _validateSecret(key, value) {
    if (!value) {
      throw new Error(`Secret '${key}' is empty`);
    }

    const minLengths = {
      'JWT_SECRET': 32,
      'SESSION_SECRET': 32,
      'DB_PASSWORD': 16,
      'API_KEY': 20
    };

    const minLength = minLengths[key] || 16;
    if (value.length < minLength) {
      throw new Error(`Secret '${key}' is too short (min: ${minLength} chars)`);
    }

    // Check for weak/default secrets
    const weakSecrets = [
      'change-this-secret-in-production',
      'your-super-secret',
      'password',
      'secret',
      '12345678',
      'admin123'
    ];

    if (weakSecrets.some(weak => value.toLowerCase().includes(weak))) {
      throw new Error(`Secret '${key}' appears to be a default or weak value`);
    }
  }

  _isWeakSecret(value) {
    // Check entropy
    const uniqueChars = new Set(value).size;
    const entropy = uniqueChars / value.length;

    if (entropy < 0.5) return true; // Low entropy
    if (value === value.toUpperCase() || value === value.toLowerCase()) return true; // No case mix
    if (!/\d/.test(value)) return true; // No numbers
    if (!/[!@#$%^&*(),.?":{}|<>]/.test(value)) return true; // No special chars

    return false;
  }

  _audit(event, key, details = null) {
    const entry = {
      timestamp: new Date().toISOString(),
      event,
      key,
      details,
      environment: this.environment
    };

    this.auditLog.push(entry);

    // Keep only last 1000 entries
    if (this.auditLog.length > 1000) {
      this.auditLog.shift();
    }

    // Log to console in development
    if (this.environment === 'development') {
      console.log(`[SECRETS_AUDIT] ${event}: ${key}`);
    }
  }
}

// Singleton instance
let instance = null;

/**
