};

// AWS Secrets Manager Integration
// Production-ready implementation for AWS environments

const { SecretsManagerClient, GetSecretValueCommand, RotateSecretCommand } = require('@aws-sdk/client-secrets-manager');

class AWSSecretsProvider {
  constructor(options = {}) {
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.environment = options.environment || process.env.NODE_ENV || 'production';
    this.secretPrefix = options.secretPrefix || `${this.environment}/`;
    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 300000; // 5 minutes

    this.client = new SecretsManagerClient({
      region: this.region,
      // Use IAM role in production, credentials in development
      ...(options.credentials && { credentials: options.credentials })
    });
  }

  /**
   * Get a single secret
   */
  async getSecret(secretName) {
    const fullName = this._getFullSecretName(secretName);

    // Check cache
    const cached = this._getFromCache(fullName);
    if (cached) return cached;

    try {
      console.log(`[AWS_SECRETS] Fetching secret: ${fullName}`);

      const command = new GetSecretValueCommand({ SecretId: fullName });
      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        // Parse JSON secrets
        try {
          const parsed = JSON.parse(response.SecretString);
          secretValue = parsed;
        } catch {
          // Single value secret
          secretValue = response.SecretString;
        }
      } else if (response.SecretBinary) {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      // Cache the secret
      this._addToCache(fullName, secretValue);

      console.log(`[AWS_SECRETS] Successfully retrieved: ${fullName}`);
      return secretValue;

    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        console.error(`[AWS_SECRETS] Secret not found: ${fullName}`);
        return null;
      }

      console.error(`[AWS_SECRETS] Error fetching secret ${fullName}:`, error.message);
      throw error;
    }
  }

  /**
   * Get multiple secrets in batch
   */
  async getSecrets(secretNames) {
    const secrets = {};

    // Fetch all secrets in parallel
    await Promise.all(
      secretNames.map(async (name) => {
        secrets[name] = await this.getSecret(name);
      })
    );

    return secrets;
  }

  /**
   * Get all application secrets (stored as JSON object)
   */
  async getApplicationSecrets() {
    const appSecretsName = this._getFullSecretName('application');

    try {
      const secrets = await this.getSecret('application');

      if (typeof secrets === 'object') {
        return secrets;
      }

      console.warn('[AWS_SECRETS] Application secrets is not a JSON object');
      return {};

    } catch (error) {
      console.error('[AWS_SECRETS] Failed to fetch application secrets:', error.message);
      throw error;
    }
  }

  /**
   * Rotate a secret
   */
  async rotateSecret(secretName) {
    const fullName = this._getFullSecretName(secretName);

    try {
      console.log(`[AWS_SECRETS] Rotating secret: ${fullName}`);

      const command = new RotateSecretCommand({
        SecretId: fullName,
        RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN
      });

      await this.client.send(command);

      // Clear cache
      this.cache.delete(fullName);

      console.log(`[AWS_SECRETS] Successfully rotated: ${fullName}`);

    } catch (error) {
      console.error(`[AWS_SECRETS] Error rotating secret ${fullName}:`, error.message);
      throw error;
    }
  }

  /**
   * Clear cache
   */
  clearCache() {
    console.log('[AWS_SECRETS] Clearing cache');
    this.cache.clear();
  }

  // Private methods

  _getFullSecretName(name) {
    return `${this.secretPrefix}${name}`;
  }

  _getFromCache(key) {
    const cached = this.cache.get(key);
    if (!cached) return null;

    const now = Date.now();
    if (now - cached.timestamp > this.cacheTTL) {
      this.cache.delete(key);
      return null;
    }

    return cached.value;
  }

  _addToCache(key, value) {
    this.cache.set(key, {
      value,
      timestamp: Date.now()
    });
  }
}

/**
 * Initialize AWS secrets for Express app
 */
async function initAWSSecrets(app, options = {}) {
  const provider = new AWSSecretsProvider(options);

  try {
    // Fetch all application secrets
    const secrets = await provider.getApplicationSecrets();

    // Make secrets available to app
    app.locals.secrets = secrets;

    // Validate required secrets
    const required = ['JWT_SECRET', 'SESSION_SECRET'];
    const missing = required.filter(key => !secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    console.log('[AWS_SECRETS] All secrets loaded successfully');
    return secrets;

  } catch (error) {
    console.error('[AWS_SECRETS] Failed to initialize:', error.message);
    throw error;
  }
}

/**
 * Middleware to refresh secrets periodically
 */
function refreshSecretsMiddleware(provider, intervalMs = 3600000) {
  setInterval(async () => {
    console.log('[AWS_SECRETS] Refreshing secrets cache...');
    provider.clearCache();
    await provider.getApplicationSecrets();
  }, intervalMs);

  return (req, res, next) => next();
}

module.exports = {
  AWSSecretsProvider,
  initAWSSecrets,
  refreshSecretsMiddleware
};

// HashiCorp Vault Integration
// Production-ready implementation for Vault secrets management

const vault = require('node-vault');

class VaultSecretsProvider {
  constructor(options = {}) {
    this.environment = options.environment || process.env.NODE_ENV || 'production';
    this.mountPath = options.mountPath || 'secret';
    this.basePath = `${this.mountPath}/data/${this.environment}`;
    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 300000; // 5 minutes

    // Initialize Vault client
    this.client = vault({
      apiVersion: 'v1',
      endpoint: options.endpoint || process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: options.token || process.env.VAULT_TOKEN,
      ...(options.namespace && { namespace: options.namespace })
    });
  }

  /**
   * Initialize and authenticate with Vault
   */
  async init() {
    try {
      // Verify connection
      const health = await this.client.health();
      console.log(`[VAULT] Connected to Vault (sealed: ${health.sealed})`);

      if (health.sealed) {
        throw new Error('Vault is sealed');
      }

      // Authenticate if using AppRole
      if (process.env.VAULT_ROLE_ID && process.env.VAULT_SECRET_ID) {
        await this._authenticateAppRole();
      }

      // Verify token is valid
      const tokenInfo = await this.client.tokenLookupSelf();
      console.log(`[VAULT] Authenticated (policies: ${tokenInfo.data.policies.join(', ')})`);

      return true;
    } catch (error) {
      console.error('[VAULT] Initialization failed:', error.message);
      throw error;
    }
  }

  /**
   * Get a secret from Vault
   */
  async getSecret(key) {
    const path = `${this.basePath}/${key}`;

    // Check cache
    const cached = this._getFromCache(path);
    if (cached) return cached;

    try {
      console.log(`[VAULT] Fetching secret: ${path}`);

      const response = await this.client.read(path);
      const secretData = response.data.data;

      // Vault KV v2 stores actual secret in data.data
      const secretValue = secretData.value || secretData;

      // Cache the secret
      this._addToCache(path, secretValue);

      console.log(`[VAULT] Successfully retrieved: ${key}`);
      return secretValue;

    } catch (error) {
      if (error.response?.statusCode === 404) {
        console.error(`[VAULT] Secret not found: ${key}`);
        return null;
      }

      console.error(`[VAULT] Error fetching secret ${key}:`, error.message);
      throw error;
    }
  }

  /**
   * Get multiple secrets
   */
  async getSecrets(keys) {
    const secrets = {};

    await Promise.all(
      keys.map(async (key) => {
        secrets[key] = await this.getSecret(key);
      })
    );

    return secrets;
  }

  /**
   * Write a secret to Vault
   */
  async setSecret(key, value) {
    const path = `${this.basePath}/${key}`;

    try {
      console.log(`[VAULT] Writing secret: ${path}`);

      await this.client.write(path, {
        data: { value }
      });

      // Clear cache
      this.cache.delete(path);

      console.log(`[VAULT] Successfully wrote: ${key}`);

    } catch (error) {
      console.error(`[VAULT] Error writing secret ${key}:`, error.message);
      throw error;
    }
  }

  /**
   * Delete a secret from Vault
   */
  async deleteSecret(key) {
    const path = `${this.basePath}/${key}`;

    try {
      console.log(`[VAULT] Deleting secret: ${path}`);

      await this.client.delete(path);

      // Clear cache
      this.cache.delete(path);

      console.log(`[VAULT] Successfully deleted: ${key}`);

    } catch (error) {
      console.error(`[VAULT] Error deleting secret ${key}:`, error.message);
      throw error;
    }
  }

  /**
   * Get a dynamic database credential
   */
  async getDatabaseCredential(role) {
    try {
      console.log(`[VAULT] Requesting database credential for role: ${role}`);

      const response = await this.client.read(`database/creds/${role}`);
      const { username, password } = response.data;

      console.log(`[VAULT] Generated database credential: ${username}`);

      return { username, password, lease_id: response.lease_id };

    } catch (error) {
      console.error(`[VAULT] Error getting database credential:`, error.message);
      throw error;
    }
  }

  /**
   * Renew a lease
   */
  async renewLease(leaseId, increment = 3600) {
    try {
      console.log(`[VAULT] Renewing lease: ${leaseId}`);

      const response = await this.client.write('sys/leases/renew', {
        lease_id: leaseId,
        increment
      });

      console.log(`[VAULT] Lease renewed until: ${new Date(Date.now() + response.lease_duration * 1000).toISOString()}`);

      return response;

    } catch (error) {
      console.error(`[VAULT] Error renewing lease:`, error.message);
      throw error;
    }
  }

  /**
   * Revoke a lease
   */
  async revokeLease(leaseId) {
    try {
      console.log(`[VAULT] Revoking lease: ${leaseId}`);

      await this.client.write('sys/leases/revoke', {
        lease_id: leaseId
      });

      console.log(`[VAULT] Lease revoked: ${leaseId}`);

    } catch (error) {
      console.error(`[VAULT] Error revoking lease:`, error.message);
      throw error;
    }
  }

  /**
   * Get transit encryption key
   */
  async encrypt(key, plaintext) {
    try {
      const response = await this.client.write(`transit/encrypt/${key}`, {
        plaintext: Buffer.from(plaintext).toString('base64')
      });

      return response.data.ciphertext;

    } catch (error) {
      console.error(`[VAULT] Encryption failed:`, error.message);
      throw error;
    }
  }

  /**
   * Decrypt with transit key
   */
  async decrypt(key, ciphertext) {
    try {
      const response = await this.client.write(`transit/decrypt/${key}`, {
        ciphertext
      });

      return Buffer.from(response.data.plaintext, 'base64').toString('utf-8');

    } catch (error) {
      console.error(`[VAULT] Decryption failed:`, error.message);
      throw error;
    }
  }

  /**
   * Clear cache
   */
  clearCache() {
    console.log('[VAULT] Clearing cache');
    this.cache.clear();
  }

  // Private methods

  async _authenticateAppRole() {
    console.log('[VAULT] Authenticating with AppRole...');

    const response = await this.client.approleLogin({
      role_id: process.env.VAULT_ROLE_ID,
      secret_id: process.env.VAULT_SECRET_ID
    });

    // Update client token
    this.client.token = response.auth.client_token;

    console.log('[VAULT] AppRole authentication successful');
  }

  _getFromCache(key) {
    const cached = this.cache.get(key);
    if (!cached) return null;

    const now = Date.now();
    if (now - cached.timestamp > this.cacheTTL) {
      this.cache.delete(key);
      return null;
    }

    return cached.value;
  }

  _addToCache(key, value) {
    this.cache.set(key, {
      value,
      timestamp: Date.now()
    });
  }
}

/**
 * Initialize Vault secrets for Express app
 */
async function initVaultSecrets(app, options = {}) {
  const provider = new VaultSecretsProvider(options);

  try {
    await provider.init();

    // Fetch required secrets
    const requiredSecrets = [
      'JWT_SECRET',
      'SESSION_SECRET',
      'DB_PASSWORD'
    ];

    const secrets = await provider.getSecrets(requiredSecrets);

    // Validate all required secrets exist
    const missing = requiredSecrets.filter(key => !secrets[key]);
    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Make secrets available to app
    app.locals.secrets = secrets;
    app.locals.vaultProvider = provider;

    console.log('[VAULT] All secrets loaded successfully');
    return secrets;

  } catch (error) {
    console.error('[VAULT] Failed to initialize:', error.message);
    throw error;
  }
}

/**
 * Middleware to manage dynamic database credentials
 */
function dynamicDBCredentialsMiddleware(provider, role) {
  let currentCreds = null;
  let renewalInterval = null;

  // Initial credential fetch
  (async () => {
    currentCreds = await provider.getDatabaseCredential(role);

    // Set up automatic renewal (renew at 80% of lease duration)
    const renewalTime = currentCreds.lease_duration * 0.8 * 1000;
    renewalInterval = setInterval(async () => {
      try {
        await provider.renewLease(currentCreds.lease_id);
      } catch (error) {
        console.error('[VAULT] Failed to renew lease, fetching new credential');
        currentCreds = await provider.getDatabaseCredential(role);
      }
    }, renewalTime);
  })();

  // Cleanup on shutdown
  process.on('SIGTERM', async () => {
    if (renewalInterval) clearInterval(renewalInterval);
    if (currentCreds) await provider.revokeLease(currentCreds.lease_id);
  });

  return (req, res, next) => {
    req.dbCredentials = currentCreds;
    next();
  };
}

module.exports = {
  VaultSecretsProvider,
  initVaultSecrets,
  dynamicDBCredentialsMiddleware
};

