 */
const WEAK_SECRETS = [
  'change-this-secret-in-production',
  'your-super-secret-jwt-key',
  'your-session-secret',
  'your_secure_password',
  'password',
  'secret',
  'admin',
  '12345678',
  'qwerty',
  'abc123'
];

/**
 * Validate a single secret
 */
function validateSecret(key, value, requirements) {
  const issues = [];

  // Check if required
  if (requirements.required && !value) {
    return {
      valid: false,
      issues: [`Missing required secret`]
    };
  }

  if (!value) {
    return { valid: true, issues: [] }; // Optional and not provided
  }

  // Check length
  if (requirements.minLength && value.length < requirements.minLength) {
    issues.push(`Too short (min: ${requirements.minLength}, got: ${value.length})`);
  }

  if (requirements.maxLength && value.length > requirements.maxLength) {
    issues.push(`Too long (max: ${requirements.maxLength}, got: ${value.length})`);
  }

  if (requirements.exactLength && value.length !== requirements.exactLength) {
    issues.push(`Must be exactly ${requirements.exactLength} characters (got: ${value.length})`);
  }

  // Check for weak/default values
  const lowerValue = value.toLowerCase();
  const weakMatch = WEAK_SECRETS.find(weak => lowerValue.includes(weak.toLowerCase()));
  if (weakMatch) {
    issues.push(`Contains weak/default value: "${weakMatch}"`);
  }

  // Check character requirements
  if (requirements.mustHaveNumbers && !/\d/.test(value)) {
    issues.push('Must contain at least one number');
  }

  if (requirements.mustHaveSpecialChars && !/[!@#$%^&*(),.?":{}|<>_\-+=\[\]\\\/]/.test(value)) {
    issues.push('Must contain at least one special character');
  }

  if (requirements.mustHaveMixedCase) {
    if (!/[a-z]/.test(value)) {
      issues.push('Must contain at least one lowercase letter');
    }
    if (!/[A-Z]/.test(value)) {
      issues.push('Must contain at least one uppercase letter');
    }
  }

  if (requirements.mustBeHex && !/^[0-9a-fA-F]+$/.test(value)) {
    issues.push('Must be a valid hexadecimal string');
  }

  // Check entropy
  const entropy = calculateEntropy(value);
  if (entropy < 3.0) {
    issues.push(`Low entropy (${entropy.toFixed(2)}/5.0) - consider using more varied characters`);
  }

  // Check for common patterns
  if (hasCommonPatterns(value)) {
    issues.push('Contains common patterns (sequential chars, repeated chars, etc.)');
  }

  return {
    valid: issues.length === 0,
    issues,
    entropy: entropy.toFixed(2)
  };
}

/**
 * Calculate Shannon entropy of a string
 */
function calculateEntropy(str) {
  const len = str.length;
  const frequencies = {};

  for (let i = 0; i < len; i++) {
    const char = str[i];
    frequencies[char] = (frequencies[char] || 0) + 1;
  }

  let entropy = 0;
  for (const freq of Object.values(frequencies)) {
    const p = freq / len;
    entropy -= p * Math.log2(p);
  }

  return entropy;
}

/**
 * Check for common weak patterns
 */
function hasCommonPatterns(str) {
  // Check for repeated characters (more than 3 in a row)
  if (/(.)\1{3,}/.test(str)) return true;

  // Check for sequential characters
  for (let i = 0; i < str.length - 3; i++) {
    const codes = str.slice(i, i + 4).split('').map(c => c.charCodeAt(0));
    const diffs = codes.slice(1).map((code, idx) => code - codes[idx]);
    if (diffs.every(d => d === 1) || diffs.every(d => d === -1)) {
      return true;
    }
  }

  return false;
}

/**
 * Generate a secure random secret
 */
function generateSecureSecret(length = 32) {
  return crypto.randomBytes(length).toString('base64').slice(0, length);
}

/**
 * Main validation function
 */
function validateAllSecrets() {
  console.log(`${colors.cyan}╔════════════════════════════════════════════════════════════╗${colors.reset}`);
  console.log(`${colors.cyan}║           🔒 SECRET VALIDATION REPORT 🔒                  ║${colors.reset}`);
