#!/usr/bin/env node

// Secret Generator Script
// Generates cryptographically secure secrets for all requirements

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  bold: '\x1b[1m'
};

/**
 * Generate a secure random string
 */
function generateSecureSecret(length, options = {}) {
  const {
    useSpecialChars = true,
    useNumbers = true,
    useUpperCase = true,
    useLowerCase = true,
    hexOnly = false
  } = options;

  if (hexOnly) {
    return crypto.randomBytes(length / 2).toString('hex');
  }

  let chars = '';
  if (useLowerCase) chars += 'abcdefghijklmnopqrstuvwxyz';
  if (useUpperCase) chars += 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  if (useNumbers) chars += '0123456789';
  if (useSpecialChars) chars += '!@#$%^&*()_+-=[]{}|;:,.<>?';

  let secret = '';
  const randomBytes = crypto.randomBytes(length * 2);

  for (let i = 0; i < length; i++) {
    const randomIndex = randomBytes[i] % chars.length;
    secret += chars[randomIndex];
  }

  return secret;
}

/**
 * Generate all required secrets
 */
function generateAllSecrets() {
  return {
    JWT_SECRET: generateSecureSecret(64),
    SESSION_SECRET: generateSecureSecret(64),
    DB_PASSWORD: generateSecureSecret(32),
    ENCRYPTION_KEY: generateSecureSecret(32, { hexOnly: true }),
    API_KEY: generateSecureSecret(40),
    CSRF_SECRET: generateSecureSecret(32),
    COOKIE_SECRET: generateSecureSecret(32)
  };
}

/**
 * Create .env file with generated secrets
 */
function createEnvFile(secrets, outputPath = '.env') {
  const envContent = `# Auto-generated secrets - ${new Date().toISOString()}
# NEVER commit this file to version control!

# Application
NODE_ENV=production
PORT=3000
HOST=0.0.0.0

# Security Secrets
JWT_SECRET=${secrets.JWT_SECRET}
SESSION_SECRET=${secrets.SESSION_SECRET}
CSRF_SECRET=${secrets.CSRF_SECRET}
COOKIE_SECRET=${secrets.COOKIE_SECRET}
ENCRYPTION_KEY=${secrets.ENCRYPTION_KEY}

# Database
DB_HOST=localhost
DB_PORT=5432
DB_NAME=your_database
DB_USER=your_user
DB_PASSWORD=${secrets.DB_PASSWORD}

# Third-party Services
