LOG_FILE_PATH=/var/log/app/app.log
`;

  fs.writeFileSync(outputPath, envContent, { mode: 0o600 });
  console.log(`${colors.green}✓ Created ${outputPath}${colors.reset}`);
}

/**
 * Display generated secrets
 */
function displaySecrets(secrets) {
  console.log(`\n${colors.cyan}${colors.bold}╔════════════════════════════════════════════════════════════╗${colors.reset}`);
  console.log(`${colors.cyan}${colors.bold}║           🔐 GENERATED SECRETS 🔐                          ║${colors.reset}`);
  console.log(`${colors.cyan}${colors.bold}╚════════════════════════════════════════════════════════════╝${colors.reset}\n`);

  for (const [key, value] of Object.entries(secrets)) {
    console.log(`${colors.blue}${key}:${colors.reset}`);
    console.log(`  ${value}`);
    console.log(`  Length: ${value.length} characters\n`);
  }
}

/**
 * Main function
 */
function main() {
  const args = process.argv.slice(2);
  const options = {
    output: '.env',
    display: true,
    force: false
  };

  // Parse command line arguments
  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--output':
      case '-o':
        options.output = args[++i];
        break;
      case '--no-display':
        options.display = false;
        break;
      case '--force':
      case '-f':
        options.force = true;
        break;
      case '--help':
      case '-h':
        console.log(`
Secret Generator

Usage: node generate-secrets.js [options]

Options:
  -o, --output <file>    Output file (default: .env)
  --no-display           Don't display secrets in terminal
  -f, --force            Overwrite existing file
  -h, --help             Show this help message

Examples:
  node generate-secrets.js
  node generate-secrets.js -o .env.production
  node generate-secrets.js --force
        `);
        process.exit(0);
    }
  }

  // Check if file exists
  if (fs.existsSync(options.output) && !options.force) {
    console.log(`${colors.yellow}⚠ File ${options.output} already exists!${colors.reset}`);
    console.log(`Use --force to overwrite, or specify a different output file with --output\n`);
    process.exit(1);
  }

  // Generate secrets
  console.log(`${colors.cyan}Generating cryptographically secure secrets...${colors.reset}\n`);
  const secrets = generateAllSecrets();

  // Display secrets
  if (options.display) {
    displaySecrets(secrets);
  }

  // Create .env file
  createEnvFile(secrets, options.output);

  // Security warnings
  console.log(`${colors.cyan}═══════════════════════════════════════════════════════════${colors.reset}\n`);
  console.log(`${colors.yellow}${colors.bold}⚠ IMPORTANT SECURITY NOTES:${colors.reset}\n`);
  console.log(`  1. ${colors.bold}NEVER${colors.reset} commit ${options.output} to version control`);
  console.log(`  2. Add "${options.output}" to .gitignore immediately`);
  console.log(`  3. Store secrets securely (use a password manager)`);
  console.log(`  4. Use different secrets for each environment`);
  console.log(`  5. Rotate secrets regularly (every 90 days minimum)`);
  console.log(`  6. In production, use a secrets manager (AWS, Vault, etc.)`);
  console.log(`  7. Never share secrets via email, chat, or screenshots\n`);

  console.log(`${colors.green}✓ Secrets generated successfully!${colors.reset}\n`);

  // Check .gitignore
  const gitignorePath = path.join(process.cwd(), '.gitignore');
  if (fs.existsSync(gitignorePath)) {
    const gitignoreContent = fs.readFileSync(gitignorePath, 'utf-8');
    if (!gitignoreContent.includes('.env')) {
      console.log(`${colors.yellow}⚠ Warning: .env is not in .gitignore${colors.reset}`);
      console.log(`Run: echo ".env" >> .gitignore\n`);
    }
  } else {
    console.log(`${colors.yellow}⚠ Warning: .gitignore file not found${colors.reset}`);
    console.log(`Run: echo ".env" > .gitignore\n`);
  }
}

if (require.main === module) {
  main();
}

