  const required = {
    JWT_SECRET: { minLength: 32, description: 'JWT signing key' },
    SESSION_SECRET: { minLength: 32, description: 'Session encryption key' },
    NODE_ENV: { values: ['development', 'production', 'test'], description: 'Environment' }
  };

  const errors = [];

  for (const [key, config] of Object.entries(required)) {
    const value = process.env[key];

    if (!value) {
      errors.push(`❌ ${key} is not set (${config.description})`);
      continue;
    }

    // Check allowed values
    if (config.values && !config.values.includes(value)) {
      errors.push(`❌ ${key} must be one of: ${config.values.join(', ')}`);
    }

    // Check minimum length
    if (config.minLength && value.length < config.minLength) {
      errors.push(`❌ ${key} is too short (min: ${config.minLength}, got: ${value.length})`);
    }

    // Check for weak/default values
    const weakSecrets = [
      'change-this-secret-in-production',
      'your-super-secret',
      'password',
      'secret',
      '12345678'
    ];

    if (weakSecrets.some(weak => value.toLowerCase().includes(weak))) {
      errors.push(`❌ ${key} contains a default/weak value - change it immediately!`);
    }

    // Warn about low entropy
    const uniqueChars = new Set(value).size;
    if (uniqueChars < value.length * 0.5) {
      console.warn(`⚠️  ${key} has low entropy - consider regenerating`);
    }
  }

  if (errors.length > 0) {
    console.error('\n🔴 SECRET VALIDATION FAILED:\n');
    errors.forEach(err => console.error(`   ${err}`));
    console.error('\n💡 To fix this:');
    console.error('   1. Copy .env.example to .env');
    console.error('   2. Run: node scripts/generate-secrets.js');
    console.error('   3. Or generate manually: node -e "console.log(require(\'crypto\').randomBytes(32).toString(\'hex\'))"\n');

    // In production, fail hard. In development, warn but allow.
    if (process.env.NODE_ENV === 'production') {
      process.exit(1);
    } else {
      console.warn('⚠️  Running in development mode with invalid secrets - DO NOT deploy!\n');
    }
  } else {
    console.log('✅ All secrets validated successfully\n');
  }
}

