const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Authentication required',
      message: 'No token provided' 
    });
  }

  // Use secret from secure storage
  jwt.verify(token, secrets.jwt.secret, { algorithms: [secrets.jwt.algorithm] }, (err, user) => {
    if (err) {
      console.warn(`[SECURITY] Invalid token attempt from IP ${req.ip}`);
      return res.status(403).json({ 
        error: 'Invalid token',
        message: 'Token verification failed' 
      });
    }
    req.user = user;
    next();
  });
};

const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!roles.includes(req.user.role)) {
      console.warn(`[SECURITY] Unauthorized access attempt: User ${req.user.id} tried to access ${req.path}`);
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        message: 'You do not have access to this resource' 
      });
    }

    next();
  };
};

