## 📋 Secrets Management Best Practices

### 1. **Secret Rotation Policy**
```javascript
// secret-rotation-check.js
const ROTATION_WARNING_DAYS = 30;
const ROTATION_REQUIRED_DAYS = 90;

async function checkSecretAge(secretName) {
  const metadata = await secretsManager.getSecretMetadata(secretName);
  const age = Date.now() - new Date(metadata.lastRotated);
  const ageDays = age / (1000 * 60 * 60 * 24);

  if (ageDays > ROTATION_REQUIRED_DAYS) {
    throw new Error(`Secret ${secretName} MUST be rotated! Age: ${ageDays} days`);
  } else if (ageDays > ROTATION_WARNING_DAYS) {
    console.warn(`Warning: Secret ${secretName} should be rotated soon. Age: ${ageDays} days`);
  }
}
```

### 2. **Secret Access Auditing**
```javascript
// audit-logger.js
const winston = require('winston');

const auditLogger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'audit-secrets.log' })
  ]
});

function auditSecretAccess(secretName, action, user) {
  auditLogger.info({
    timestamp: new Date().toISOString(),
    secretName,
    action, // 'read', 'write', 'delete'
    user,
    source: 'application'
  });
}
