### 3. **Secrets Rotation Script**
```javascript
// scripts/rotate-secrets.js
const { 
  SecretsManagerClient, 
  UpdateSecretCommand,
  RotateSecretCommand 
} = require('@aws-sdk/client-secrets-manager');
const crypto = require('crypto');

async function rotateJWTSecret() {
  const client = new SecretsManagerClient({ region: 'us-east-1' });

  // Generate new secret
  const newSecret = crypto.randomBytes(64).toString('hex');

  // Update in Secrets Manager
  const command = new RotateSecretCommand({
    SecretId: 'myapp/jwt-secret',
    RotationLambdaARN: 'arn:aws:lambda:...',
  });

  await client.send(command);
  console.log('✓ JWT secret rotated successfully');
}

// Run rotation
if (require.main === module) {
  rotateJWTSecret().catch(console.error);
}
```

### 4. **Secret Scanning Pre-commit Hook**
```bash
#!/bin/bash
# .git/hooks/pre-commit

# Check for potential secrets in staged files
if git diff --cached | grep -E '(password|secret|key|token|api_key).*=.*[A-Za-z0-9+/]{20,}'; then
    echo "⚠️  WARNING: Potential secret detected in staged files!"
    echo "Please review and remove any secrets before committing."
    exit 1
fi

# Use git-secrets or truffleHog
git secrets --scan
```

