```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT'
      });

      const response = await this.client.send(command);
      const secret = response.SecretString ? JSON.parse(response.SecretString) : response.SecretBinary;

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getDatabaseCredentials() {
    return await this.getSecret('prod/database/credentials');
  }

  async getAPIKeys() {
    return await this.getSecret('prod/api/keys');
  }

  async getStripeKey() {
    const secrets = await this.getSecret('prod/stripe/credentials');
    return secrets.secret_key;
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new SecretsManager();
