// config/secret-rotation.js
const cron = require('node-cron');

class SecretRotationService {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
  }

  // Run daily at 3 AM
  startRotationCheck() {
    cron.schedule('0 3 * * *', async () => {
      console.log('Checking for secret rotation...');
      await this.rotateSecrets();
    });
  }

  async rotateSecrets() {
    try {
      // Clear cache to force fresh fetch
      this.secretsManager.clearCache();

      // Reload secrets
      const newSecrets = await this.secretsManager.getSecret('app/production/secrets');

      console.log('✓ Secrets rotated successfully');
      return newSecrets;
    } catch (error) {
      console.error('✗ Secret rotation failed:', error);
      // Alert ops team
    }
  }
}

module.exports = SecretRotationService;
