/**
 * AWS Secrets Manager Integration
 * Securely retrieve secrets from AWS Secrets Manager
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      // Uses IAM roles in production, no hardcoded credentials needed
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Get secret from AWS Secrets Manager with caching
   * @param {string} secretName - Name of the secret in AWS
   * @param {boolean} forceRefresh - Force refresh from AWS
   * @returns {Promise<Object>} - Secret value as object
   */
  async getSecret(secretName, forceRefresh = false) {
    const now = Date.now();
    const cached = this.cache.get(secretName);

    // Return cached value if valid
    if (!forceRefresh && cached && (now - cached.timestamp) < this.cacheTTL) {
      console.log(`[SecretsManager] Using cached secret: ${secretName}`);
      return cached.value;
    }

    try {
      console.log(`[SecretsManager] Fetching secret from AWS: ${secretName}`);

      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT', // Use current version
      });

      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secretValue = buff.toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: now
      });

      return secretValue;
    } catch (error) {
      console.error(`[SecretsManager] Error fetching secret ${secretName}:`, error.message);

      // Return cached value if available (degraded mode)
      if (cached) {
        console.warn(`[SecretsManager] Using stale cached secret: ${secretName}`);
        return cached.value;
      }

      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Invalidate cache for a specific secret or all secrets
   * @param {string|null} secretName - Secret name or null for all
   */
  invalidateCache(secretName = null) {
    if (secretName) {
      this.cache.delete(secretName);
      console.log(`[SecretsManager] Cache invalidated for: ${secretName}`);
    } else {
      this.cache.clear();
      console.log('[SecretsManager] All cache invalidated');
    }
  }

  /**
   * Get database connection string securely
   * @returns {Promise<string>}
   */
  async getDatabaseUrl() {
    const secrets = await this.getSecret('production/database');
    return `postgres://${secrets.username}:${secrets.password}@${secrets.host}:${secrets.port}/${secrets.database}`;
  }

  /**
   * Get all application secrets
   * @returns {Promise<Object>}
   */
  async getAllSecrets() {
    const secretName = process.env.NODE_ENV === 'production' 
      ? 'production/app-secrets'
      : 'development/app-secrets';

    return await this.getSecret(secretName);
  }
}

// Singleton instance
let instance = null;

function getSecretsManager() {
  if (!instance) {
    instance = new SecretsManager();
  }
  return instance;
}

module.exports = { SecretsManager, getSecretsManager };

/**
 * HashiCorp Vault Integration
 * Securely retrieve secrets from Vault
 */

const vault = require('node-vault');

class VaultSecretsManager {
  constructor() {
    this.client = null;
    this.initialized = false;
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Initialize Vault client
   */
  async initialize() {
    if (this.initialized) return;

    const vaultConfig = {
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
    };

    // Use AppRole authentication (recommended for applications)
    if (process.env.VAULT_ROLE_ID && process.env.VAULT_SECRET_ID) {
      this.client = vault(vaultConfig);

      try {
        const result = await this.client.approleLogin({
          role_id: process.env.VAULT_ROLE_ID,
          secret_id: process.env.VAULT_SECRET_ID,
        });

        this.client.token = result.auth.client_token;
        console.log('[Vault] Successfully authenticated with AppRole');
      } catch (error) {
        throw new Error(`Vault authentication failed: ${error.message}`);
      }
    } 
    // Use token authentication (development only)
    else if (process.env.VAULT_TOKEN) {
      vaultConfig.token = process.env.VAULT_TOKEN;
      this.client = vault(vaultConfig);
      console.warn('[Vault] Using token authentication (not recommended for production)');
    }
    // Use Kubernetes authentication
    else if (process.env.VAULT_K8S_ROLE) {
      this.client = vault(vaultConfig);
      const jwt = require('fs').readFileSync(
        '/var/run/secrets/kubernetes.io/serviceaccount/token',
        'utf8'
      );

      const result = await this.client.kubernetesLogin({
        role: process.env.VAULT_K8S_ROLE,
        jwt: jwt,
      });

      this.client.token = result.auth.client_token;
      console.log('[Vault] Successfully authenticated with Kubernetes');
    }
    else {
      throw new Error('No Vault authentication method configured');
    }

    this.initialized = true;
  }

  /**
   * Get secret from Vault with caching
   * @param {string} path - Path to secret in Vault
   * @param {boolean} forceRefresh - Force refresh from Vault
   * @returns {Promise<Object>}
   */
  async getSecret(path, forceRefresh = false) {
    await this.initialize();

    const now = Date.now();
    const cached = this.cache.get(path);

    if (!forceRefresh && cached && (now - cached.timestamp) < this.cacheTTL) {
      console.log(`[Vault] Using cached secret: ${path}`);
      return cached.value;
    }

    try {
      console.log(`[Vault] Fetching secret: ${path}`);
      const result = await this.client.read(path);
      const secretValue = result.data.data || result.data;

      this.cache.set(path, {
        value: secretValue,
        timestamp: now
      });

      return secretValue;
    } catch (error) {
      console.error(`[Vault] Error fetching secret ${path}:`, error.message);

      if (cached) {
        console.warn(`[Vault] Using stale cached secret: ${path}`);
        return cached.value;
      }

      throw new Error(`Failed to retrieve secret from Vault: ${path}`);
    }
  }

  /**
   * Get dynamic database credentials
   * @returns {Promise<Object>}
   */
  async getDatabaseCredentials() {
    const path = 'database/creds/app-role';
    const creds = await this.getSecret(path, true); // Always fresh for dynamic creds

    // Dynamic credentials have TTL, set up auto-renewal
    if (creds.lease_id) {
      this.setupLeaseRenewal(creds.lease_id, creds.lease_duration);
    }

    return {
      username: creds.username,
      password: creds.password,
      leaseId: creds.lease_id,
      leaseDuration: creds.lease_duration
    };
  }

  /**
   * Setup automatic lease renewal
   * @param {string} leaseId 
   * @param {number} leaseDuration 
   */
  setupLeaseRenewal(leaseId, leaseDuration) {
    // Renew at 80% of lease duration
    const renewalTime = leaseDuration * 0.8 * 1000;

    setTimeout(async () => {
      try {
        console.log(`[Vault] Renewing lease: ${leaseId}`);
        await this.client.renew({ lease_id: leaseId });
      } catch (error) {
        console.error('[Vault] Lease renewal failed:', error.message);
      }
    }, renewalTime);
  }

  /**
   * Invalidate cache
   */
  invalidateCache(path = null) {
    if (path) {
      this.cache.delete(path);
    } else {
      this.cache.clear();
    }
  }
}

// Singleton instance
let instance = null;

function getVaultSecretsManager() {
  if (!instance) {
    instance = new VaultSecretsManager();
  }
  return instance;
}

module.exports = { VaultSecretsManager, getVaultSecretsManager };

/**
 * Google Cloud Secret Manager Integration
 */

const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class GCPSecretsManager {
  constructor() {
    this.client = new SecretManagerServiceClient();
    this.projectId = process.env.GCP_PROJECT_ID;
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Get secret from GCP Secret Manager
   * @param {string} secretName - Name of the secret
   * @param {string} version - Version (default: 'latest')
   * @param {boolean} forceRefresh - Force refresh from GCP
   * @returns {Promise<string>}
   */
  async getSecret(secretName, version = 'latest', forceRefresh = false) {
    const cacheKey = `${secretName}:${version}`;
    const now = Date.now();
    const cached = this.cache.get(cacheKey);

    if (!forceRefresh && cached && (now - cached.timestamp) < this.cacheTTL) {
      console.log(`[GCP Secrets] Using cached secret: ${secretName}`);
      return cached.value;
    }

    try {
      const name = `projects/${this.projectId}/secrets/${secretName}/versions/${version}`;
      console.log(`[GCP Secrets] Fetching secret: ${name}`);

      const [version_data] = await this.client.accessSecretVersion({ name });
      const payload = version_data.payload.data.toString('utf8');

      let secretValue;
      try {
        secretValue = JSON.parse(payload);
      } catch {
        secretValue = payload; // Plain string secret
      }

      this.cache.set(cacheKey, {
        value: secretValue,
        timestamp: now
      });

      return secretValue;
    } catch (error) {
      console.error(`[GCP Secrets] Error fetching ${secretName}:`, error.message);

      if (cached) {
        console.warn(`[GCP Secrets] Using stale cached secret: ${secretName}`);
        return cached.value;
      }

      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Get all application secrets
   * @returns {Promise<Object>}
   */
  async getAllSecrets() {
    const env = process.env.NODE_ENV || 'development';
    return await this.getSecret(`app-secrets-${env}`);
  }

  invalidateCache(secretName = null) {
    if (secretName) {
      for (const key of this.cache.keys()) {
        if (key.startsWith(secretName)) {
          this.cache.delete(key);
        }
      }
    } else {
      this.cache.clear();
    }
  }
}

let instance = null;

function getGCPSecretsManager() {
  if (!instance) {
    instance = new GCPSecretsManager();
  }
  return instance;
}

module.exports = { GCPSecretsManager, getGCPSecretsManager };

/**
 * Secure Express Application with Secrets Manager Integration
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const morgan = require('morgan');
const winston = require('winston');

// Import secrets manager (choose one based on your infrastructure)
const { getSecretsManager } = require('./secrets-manager-aws');
// const { getVaultSecretsManager } = require('./secrets-manager-vault');
// const { getGCPSecretsManager } = require('./secrets-manager-gcp');

const app = express();
let appSecrets = null;

// ===== LOGGING SETUP =====
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

/**
 * Initialize application with secrets
 */
async function initializeApp() {
  try {
    logger.info('Initializing application...');

    // Load secrets from secrets manager
    const secretsManager = getSecretsManager();
    appSecrets = await secretsManager.getAllSecrets();

    logger.info('Secrets loaded successfully');

    // Validate required secrets
    const requiredSecrets = [
      'JWT_SECRET',
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    for (const secret of requiredSecrets) {
      if (!appSecrets[secret]) {
        throw new Error(`Missing required secret: ${secret}`);
      }
    }

    logger.info('All required secrets validated');

  } catch (error) {
    logger.error('Failed to initialize application:', error);
    process.exit(1);
  }
}

/**
 * Get secret value safely
 * @param {string} key - Secret key
 * @param {string} defaultValue - Default value if secret not found
 * @returns {string}
 */
function getSecret(key, defaultValue = null) {
  if (!appSecrets) {
    throw new Error('Secrets not initialized. Call initializeApp() first.');
  }

  const value = appSecrets[key];

  if (!value && !defaultValue) {
    logger.error(`Secret not found: ${key}`);
    throw new Error(`Missing secret: ${key}`);
  }

  return value || defaultValue;
}

// ===== SECURITY MIDDLEWARE =====

app.use(morgan('combined', {
  stream: { write: (message) => logger.info(message.trim()) }
}));

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS - get allowed origins from secrets
app.use((req, res, next) => {
  if (!appSecrets) return next();

  const allowedOrigins = appSecrets.CORS_WHITELIST?.split(',') || ['http://localhost:3000'];
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Credentials', 'true');
  }

  next();
});

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(mongoSanitize());
app.use(xss());
app.use(hpp());

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn({
      type: 'RATE_LIMIT_EXCEEDED',
      ip: req.ip,
      path: req.path
    });
    res.status(429).json({
      error: 'Too many requests, please try again later.'
    });
  }
});
app.use(limiter);

// HTTPS redirect
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && 
      !req.secure && 
      req.get('x-forwarded-proto') !== 'https') {
    return res.redirect(301, 'https://' + req.get('host') + req.url);
  }
  next();
});

// ===== AUTHENTICATION MIDDLEWARE =====
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      type: 'AUTH_MISSING_TOKEN',
      ip: req.ip,
      path: req.path
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  // Use JWT secret from secrets manager
  const jwtSecret = getSecret('JWT_SECRET');

  jwt.verify(token, jwtSecret, (err, user) => {
    if (err) {
      logger.warn({
        type: 'AUTH_INVALID_TOKEN',
        ip: req.ip,
        path: req.path,
        error: err.message
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ===== ROUTES =====

// Health check - includes secrets status
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    secretsLoaded: !!appSecrets
  });
});

// Protected users endpoint
app.get('/users', authenticateToken, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const sanitizedUsers = users.map(u => ({
      id: u.id,
      name: u.name,
      ...(req.user.role === 'admin' ? { email: u.email } : {})
    }));

    logger.info({
      type: 'USERS_ACCESSED',
      userId: req.user.id,
      userRole: req.user.role
    });

    res.json(sanitizedUsers);
  } catch (error) {
    logger.error({
      type: 'USERS_ERROR',
      error: error.message,
      stack: error.stack
    });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Endpoint to test external service connectivity (using secrets)
app.get('/api/external-test', authenticateToken, async (req, res) => {
  try {
    // Example: Use AWS credentials from secrets manager
    const awsKeyId = getSecret('AWS_ACCESS_KEY_ID');

    // Log that we're using the secret (but never log the actual value!)
    logger.info({
      type: 'EXTERNAL_SERVICE_TEST',
      service: 'aws',
      keyIdPrefix: awsKeyId.substring(0, 8) + '...' // Only log prefix
    });

    res.json({ 
      status: 'success',
      message: 'External service credentials loaded from secrets manager'
    });
  } catch (error) {
    logger.error('External service test failed:', error);
    res.status(500).json({ error: 'Failed to access external service' });
  }
});

// Admin endpoint to refresh secrets (requires admin role)
app.post('/api/admin/refresh-secrets', authenticateToken, async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      logger.warn({
        type: 'UNAUTHORIZED_SECRETS_REFRESH',
        userId: req.user.id
      });
      return res.status(403).json({ error: 'Admin access required' });
    }

    logger.info({
      type: 'SECRETS_REFRESH_REQUESTED',
      userId: req.user.id
    });

    const secretsManager = getSecretsManager();
    secretsManager.invalidateCache();
    appSecrets = await secretsManager.getAllSecrets();

    logger.info({
      type: 'SECRETS_REFRESHED',
      userId: req.user.id
    });

    res.json({ 
      status: 'success',
      message: 'Secrets refreshed successfully'
    });
  } catch (error) {
    logger.error('Failed to refresh secrets:', error);
    res.status(500).json({ error: 'Failed to refresh secrets' });
  }
});

// ===== ERROR HANDLING =====

app.use((req, res) => {
  logger.warn({
    type: 'NOT_FOUND',
    path: req.path,
    method: req.method,
    ip: req.ip
  });
  res.status(404).json({ error: 'Not found' });
});

app.use((err, req, res, next) => {
  logger.error({
    type: 'UNHANDLED_ERROR',
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An error occurred' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ===== SERVER STARTUP =====

async function startServer() {
  try {
    // Initialize secrets first
    await initializeApp();

    const PORT = process.env.PORT || 3000;
    const HOST = process.env.HOST || '0.0.0.0';

    const server = app.listen(PORT, HOST, () => {
      logger.info(`Server running on ${HOST}:${PORT}`);
      logger.info(`Environment: ${process.env.NODE_ENV || 'development'}`);
      logger.info('Secrets loaded from secrets manager');
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM signal received: closing HTTP server');
      server.close(() => {
        logger.info('HTTP server closed');
        process.exit(0);
      });
    });

    process.on('SIGINT', () => {
      logger.info('SIGINT signal received: closing HTTP server');
      server.close(() => {
        logger.info('HTTP server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
}

// Start the server
if (require.main === module) {
  startServer();
}

module.exports = app;

