// Secure version of app.js with comprehensive security controls
// Addresses OWASP Top 10 vulnerabilities

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const cors = require('cors');
const morgan = require('morgan');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================
// 1. SECURITY HEADERS (Helmet)
// ============================================
// Protects against: XSS, Clickjacking, MIME sniffing, etc.
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// ============================================
// 2. CORS CONFIGURATION
// ============================================
// Protects against: Unauthorized cross-origin requests
const corsOptions = {
  origin: function (origin, callback) {
    // Whitelist of allowed origins
    const allowedOrigins = [
      'https://yourdomain.com',
      'https://app.yourdomain.com'
    ];

    // Allow requests with no origin (mobile apps, Postman, etc.)
    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));

// ============================================
// 3. RATE LIMITING
// ============================================
// Protects against: DoS/DDoS, Brute Force attacks
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit each IP to 5 failed login attempts per windowMs
  message: 'Too many authentication attempts, please try again later.',
  skipSuccessfulRequests: true,
});

app.use('/api/', generalLimiter);

// ============================================
// 4. BODY PARSING WITH SIZE LIMITS
// ============================================
// Protects against: Large payload DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// 5. DATA SANITIZATION
// ============================================
// Protects against: NoSQL injection, XSS
app.use(mongoSanitize()); // Sanitize data against NoSQL injection
app.use(xss()); // Sanitize user input from XSS

// ============================================
// 6. PREVENT HTTP PARAMETER POLLUTION
// ============================================
app.use(hpp());

// ============================================
// 7. LOGGING
// ============================================
// Security logging for audit trails
if (process.env.NODE_ENV === 'production') {
  app.use(morgan('combined'));
} else {
  app.use(morgan('dev'));
}

// ============================================
// 8. AUTHENTICATION MIDDLEWARE
// ============================================
// Simple JWT authentication example
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ 
      error: 'Access denied. No token provided.' 
    });
  }

  try {
    const secret = process.env.JWT_SECRET || 'your-secret-key-change-in-production';
    const decoded = jwt.verify(token, secret);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ 
      error: 'Invalid or expired token.' 
    });
  }
};

// ============================================
// 9. INPUT VALIDATION MIDDLEWARE
// ============================================
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// 10. HTTPS ENFORCEMENT
// ============================================
const enforceHTTPS = (req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure && req.get('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.get('host')}${req.originalUrl}`);
  }
  next();
};

app.use(enforceHTTPS);

// ============================================
// ROUTES WITH SECURITY CONTROLS
// ============================================

// Health check endpoint (public, no auth needed)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint (protected, with validation)
app.get('/users', 
  authenticateToken, // Require authentication
  [
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('sort').optional().isIn(['asc', 'desc']),
    validateRequest
  ],
  (req, res) => {
    try {
      // In production, this would query a database with parameterized queries
      // Example with pagination
      const page = req.query.page || 1;
      const limit = req.query.limit || 10;

      // Hardcoded for demo - in production, use database with proper access controls
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      res.json({
        data: users,
        pagination: {
          page,
          limit,
          total: users.length
        }
      });
    } catch (error) {
      // Don't expose internal error details
      console.error('Error fetching users:', error);
      res.status(500).json({ 
        error: 'An error occurred while fetching users' 
      });
    }
  }
);

// Get single user by ID (with validation)
app.get('/users/:id',
  authenticateToken,
  [
    param('id').isInt({ min: 1 }).toInt(),
    validateRequest
  ],
  (req, res) => {
    try {
      const userId = req.params.id;

      // In production: Use parameterized queries
      // const user = await db.query('SELECT * FROM users WHERE id = $1', [userId]);

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      res.json({ data: user });
    } catch (error) {
      console.error('Error fetching user:', error);
      res.status(500).json({ 
        error: 'An error occurred while fetching user' 
      });
    }
  }
);

// Login endpoint (with rate limiting and validation)
app.post('/auth/login',
  authLimiter,
  [
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 8 }),
    validateRequest
  ],
  async (req, res) => {
