# Security Recommendations for app.js

## Executive Summary
The current `app.js` implementation has **10 critical security vulnerabilities** that expose it to OWASP Top 10 risks. This document provides detailed remediation steps.

---

## 🔴 CRITICAL VULNERABILITIES FOUND

### 1. **No Input Validation** (OWASP A03:2021 - Injection)
**Current Risk:** SQL/NoSQL injection, XSS attacks, command injection

**Issue:**
```javascript
app.get('/users', (req, res) => {
  // No validation on req.query, req.params, req.body
});
```

**Fix:** Use `express-validator` for all inputs
```javascript
const { query, param, body, validationResult } = require('express-validator');

app.get('/users/:id',
  param('id').isInt().toInt(),
  query('filter').optional().isAlphanumeric().trim().escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use validated inputs
  }
);
```

---

### 2. **Missing Authentication/Authorization** (OWASP A01:2021 - Broken Access Control)
**Current Risk:** Unauthorized access to user data

**Issue:**
```javascript
app.get('/users', (req, res) => {
  // Anyone can access sensitive user data!
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
  ]);
});
```

**Fix:** Implement JWT authentication
```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access denied' });
  }

  try {
    const verified = jwt.verify(token, process.env.JWT_SECRET);
    req.user = verified;
    next();
  } catch (err) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

app.get('/users', authenticateToken, (req, res) => {
  // Now protected
});
```

---

### 3. **No Rate Limiting** (OWASP A05:2021 - Security Misconfiguration)
**Current Risk:** DoS/DDoS attacks, brute force attacks

**Fix:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.'
});

app.use(limiter);

// Stricter limits for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true
});

app.post('/login', authLimiter, loginHandler);
```

---

### 4. **Missing Security Headers** (OWASP A05:2021 - Security Misconfiguration)
**Current Risk:** XSS, clickjacking, MIME sniffing attacks

**Fix:** Use Helmet
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
}));
```

**Headers Added:**
- `X-Content-Type-Options: nosniff`
- `X-Frame-Options: DENY`
- `Strict-Transport-Security: max-age=31536000; includeSubDomains`
- `Content-Security-Policy: default-src 'self'`
- `X-XSS-Protection: 1; mode=block`

---

### 5. **No Error Handling** (OWASP A04:2021 - Insecure Design)
**Current Risk:** Information disclosure, application crashes

**Fix:**
```javascript
// 404 Handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global Error Handler
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't expose error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({ 
    error: message 
  });
});
```

---

### 6. **No CORS Policy** (OWASP A05:2021 - Security Misconfiguration)
**Current Risk:** Cross-origin attacks, data theft

**Fix:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: function (origin, callback) {
    const whitelist = ['https://yourdomain.com', 'https://app.yourdomain.com'];
    if (whitelist.indexOf(origin) !== -1 || !origin) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));
```

---

### 7. **No Request Size Limits** (DoS Protection)
**Current Risk:** Large payload DoS attacks

**Fix:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

---

### 8. **No Data Sanitization** (OWASP A03:2021 - Injection)
**Current Risk:** NoSQL injection, XSS attacks

**Fix:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

// Remove $ and . from user input (NoSQL injection)
app.use(mongoSanitize());

// Sanitize user input from XSS
app.use(xss());
```

---

### 9. **No Security Logging** (OWASP A09:2021 - Security Logging Failures)
**Current Risk:** Cannot detect or respond to breaches

**Fix:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// HTTP request logging
app.use(morgan('combined'));

// Security event logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'security.log', level: 'warn' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Log security events
function logSecurityEvent(event, req, severity = 'warn') {
  logger.log(severity, {
    event,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date().toISOString(),
    path: req.path
  });
}
```

---

### 10. **No HTTPS Enforcement** (OWASP A02:2021 - Cryptographic Failures)
**Current Risk:** Man-in-the-middle attacks, data interception

**Fix:**
```javascript
const enforceHTTPS = (req, res, next) => {
  if (process.env.NODE_ENV === 'production' && 
      !req.secure && 
      req.get('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.get('host')}${req.originalUrl}`);
  }
  next();
};

app.use(enforceHTTPS);
```

