/**
 * Secrets Manager Configuration
 * 
 * This module handles loading secrets from various sources with proper fallbacks:
 * 1. AWS Secrets Manager (production)
 * 2. Azure Key Vault (alternative)
 * 3. HashiCorp Vault (alternative)
 * 4. Environment variables (development only)
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { SecretClient } = require('@azure/keyvault-secrets');
const { DefaultAzureCredential } = require('@azure/identity');

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.provider = process.env.SECRETS_PROVIDER || 'env'; // 'aws', 'azure', 'vault', 'env'
    this.environment = process.env.NODE_ENV || 'development';
    this.initialized = false;
  }

  /**
   * Initialize secrets from the configured provider
   */
  async initialize() {
    if (this.initialized) {
      return;
    }

    console.log(`Initializing secrets from provider: ${this.provider}`);

    try {
      switch (this.provider) {
        case 'aws':
          await this.loadFromAWS();
          break;
        case 'azure':
          await this.loadFromAzure();
          break;
        case 'vault':
          await this.loadFromVault();
          break;
        case 'env':
          this.loadFromEnvironment();
          break;
        default:
          throw new Error(`Unknown secrets provider: ${this.provider}`);
      }

      this.initialized = true;
      console.log('Secrets loaded successfully');
    } catch (error) {
      console.error('Failed to load secrets:', error.message);

      // In production, fail hard. In development, warn and continue.
      if (this.environment === 'production') {
        throw new Error('Failed to load secrets in production environment');
      } else {
        console.warn('Falling back to environment variables for development');
        this.loadFromEnvironment();
        this.initialized = true;
      }
    }
  }

  /**
   * Load secrets from AWS Secrets Manager
   */
  async loadFromAWS() {
    const client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    const secretName = process.env.AWS_SECRET_NAME || `app-secrets-${this.environment}`;

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await client.send(command);

      const secretString = response.SecretString;
      const secrets = JSON.parse(secretString);

      // Store all secrets
      Object.entries(secrets).forEach(([key, value]) => {
        this.secrets.set(key, value);
      });

      console.log(`Loaded ${this.secrets.size} secrets from AWS Secrets Manager`);
    } catch (error) {
      throw new Error(`AWS Secrets Manager error: ${error.message}`);
    }
  }

  /**
   * Load secrets from Azure Key Vault
   */
  async loadFromAzure() {
    const vaultUrl = process.env.AZURE_KEYVAULT_URL;

    if (!vaultUrl) {
      throw new Error('AZURE_KEYVAULT_URL not configured');
    }

    const credential = new DefaultAzureCredential();
    const client = new SecretClient(vaultUrl, credential);

    // List of secret names to fetch
    const secretNames = [
      'DATABASE-URL',
      'JWT-SECRET',
      'API-KEY',
      'STRIPE-SECRET-KEY',
      // Add more as needed
    ];

    try {
      for (const secretName of secretNames) {
        try {
          const secret = await client.getSecret(secretName);
          // Azure Key Vault uses hyphens, convert to underscores for consistency
          const key = secretName.replace(/-/g, '_');
          this.secrets.set(key, secret.value);
        } catch (error) {
          console.warn(`Failed to load secret ${secretName}:`, error.message);
        }
      }

      console.log(`Loaded ${this.secrets.size} secrets from Azure Key Vault`);
    } catch (error) {
      throw new Error(`Azure Key Vault error: ${error.message}`);
    }
  }

  /**
   * Load secrets from HashiCorp Vault
   */
  async loadFromVault() {
    const vault = require('node-vault')({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN,
    });

    const secretPath = process.env.VAULT_SECRET_PATH || `secret/data/app/${this.environment}`;

    try {
      const result = await vault.read(secretPath);
      const secrets = result.data.data;

      Object.entries(secrets).forEach(([key, value]) => {
        this.secrets.set(key, value);
      });

      console.log(`Loaded ${this.secrets.size} secrets from HashiCorp Vault`);
    } catch (error) {
      throw new Error(`HashiCorp Vault error: ${error.message}`);
    }
  }

  /**
   * Load secrets from environment variables (development only)
   */
  loadFromEnvironment() {
    if (this.environment === 'production') {
      console.warn('⚠️  WARNING: Using environment variables for secrets in production is not recommended!');
    }

    // Only load specific allowed environment variables
    const allowedEnvVars = [
      'DATABASE_URL',
      'JWT_SECRET',
      'API_KEY',
      'STRIPE_SECRET_KEY',
      'STRIPE_PUBLISHABLE_KEY',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN',
      'SMTP_PASSWORD',
      'ENCRYPTION_KEY',
    ];

    allowedEnvVars.forEach(key => {
      const value = process.env[key];
      if (value) {
        this.secrets.set(key, value);
      }
    });

    console.log(`Loaded ${this.secrets.size} secrets from environment variables`);
  }

  /**
   * Get a secret value
   */
  get(key) {
    if (!this.initialized) {
      throw new Error('SecretsManager not initialized. Call initialize() first.');
    }

    const value = this.secrets.get(key);

    if (!value && this.environment === 'production') {
      throw new Error(`Secret ${key} not found`);
    }

    return value;
  }

  /**
   * Get a secret value with a default fallback
   */
  getOrDefault(key, defaultValue) {
    if (!this.initialized) {
      throw new Error('SecretsManager not initialized. Call initialize() first.');
    }

    return this.secrets.get(key) || defaultValue;
  }

  /**
   * Check if a secret exists
   */
  has(key) {
    return this.secrets.has(key);
  }

  /**
   * Get all secret keys (for debugging - be careful with this!)
   */
  getKeys() {
    if (this.environment === 'production') {
      throw new Error('Cannot list secret keys in production');
    }
    return Array.from(this.secrets.keys());
  }

  /**
   * Validate that all required secrets are present
   */
  validateRequiredSecrets(requiredKeys) {
    const missing = requiredKeys.filter(key => !this.secrets.has(key));

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    return true;
  }

  /**
   * Rotate a secret (useful for key rotation policies)
   */
  async rotateSecret(key, newValue) {
    if (this.provider === 'env') {
      throw new Error('Cannot rotate secrets when using environment variables');
    }

    // Implementation depends on the provider
    // This is a placeholder for the rotation logic
    console.log(`Rotating secret: ${key}`);
    this.secrets.set(key, newValue);
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

/**
 * Application Configuration
 * 
 * Centralizes all configuration with proper validation and type safety
 */

const secretsManager = require('./secrets');

class AppConfig {
  constructor() {
    this.initialized = false;
  }

  async initialize() {
    // Initialize secrets manager first
    await secretsManager.initialize();

    // Validate all required secrets are present
    this.validateConfiguration();

    this.initialized = true;
  }

  validateConfiguration() {
    const requiredSecrets = [];

    // Add required secrets based on features enabled
    if (this.database.enabled) {
      requiredSecrets.push('DATABASE_URL');
    }

    if (this.auth.enabled) {
      requiredSecrets.push('JWT_SECRET');
    }

    if (this.stripe.enabled) {
      requiredSecrets.push('STRIPE_SECRET_KEY');
    }

    // Validate all required secrets exist
    try {
      secretsManager.validateRequiredSecrets(requiredSecrets);
    } catch (error) {
      console.error('Configuration validation failed:', error.message);
      throw error;
    }
  }

  get app() {
    return {
      name: process.env.APP_NAME || 'secure-express-app',
      version: process.env.APP_VERSION || '1.0.0',
      env: process.env.NODE_ENV || 'development',
      port: parseInt(process.env.PORT || '3000', 10),
      host: process.env.HOST || 'localhost',
    };
  }

  get database() {
    return {
      enabled: process.env.DATABASE_ENABLED !== 'false',
