    };
  }

  get anthropic() {
    return {
      enabled: process.env.ANTHROPIC_ENABLED === 'true',
      apiKey: secretsManager.getOrDefault('ANTHROPIC_API_KEY', null),
    };
  }

  get logging() {
    return {
