}

// Singleton instance
const config = new AppConfig();

module.exports = config;

/**
 * Secure Express Application with Proper Secrets Management
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');

// Import configuration (will load secrets on initialization)
const config = require('./config');

const app = express();

/**
 * Initialize application with async configuration
 */
async function initializeApp() {
  try {
    // Initialize configuration and secrets
    await config.initialize();
    console.log('✓ Configuration and secrets loaded successfully');

    // Security headers
    if (config.security.helmet.contentSecurityPolicy) {
      app.use(helmet({
        contentSecurityPolicy: {
          directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
          },
        },
        hsts: config.security.helmet.hsts ? {
          maxAge: 31536000,
          includeSubDomains: true,
          preload: true
        } : false,
      }));
    }

    // CORS configuration
    const corsOptions = {
      origin: function (origin, callback) {
        const whitelist = config.security.cors.origins;
        if (!origin || whitelist.indexOf(origin) !== -1) {
          callback(null, true);
        } else {
          callback(new Error('Not allowed by CORS'));
        }
      },
      credentials: config.security.cors.credentials,
      optionsSuccessStatus: 200
    };
    app.use(cors(corsOptions));

    // Body parsers with limits
    app.use(express.json({ limit: '10mb' }));
    app.use(express.urlencoded({ extended: true, limit: '10mb' }));

    // Request logging
    app.use(morgan(config.app.env === 'production' ? 'combined' : 'dev'));

    // Rate limiting
    const generalLimiter = rateLimit({
      windowMs: config.security.rateLimit.windowMs,
      max: config.security.rateLimit.max,
      message: 'Too many requests from this IP, please try again later.',
      standardHeaders: true,
      legacyHeaders: false,
    });

    const strictLimiter = rateLimit({
      windowMs: config.security.rateLimit.windowMs,
      max: Math.floor(config.security.rateLimit.max / 5),
      message: 'Too many requests, please try again later.',
    });

    app.use(generalLimiter);

    // Authentication middleware
    const authenticateToken = (req, res, next) => {
      const authHeader = req.headers['authorization'];
      const token = authHeader && authHeader.split(' ')[1];

      if (!token) {
        return res.status(401).json({ error: 'Access denied. No token provided.' });
      }

      try {
        // Use JWT secret from secure configuration
        const verified = jwt.verify(token, config.auth.jwtSecret);
        req.user = verified;
        next();
      } catch (error) {
        res.status(403).json({ error: 'Invalid or expired token' });
      }
    };

    // Authorization middleware
    const authorize = (...roles) => {
      return (req, res, next) => {
        if (!roles.includes(req.user.role)) {
          return res.status(403).json({ error: 'Insufficient permissions' });
        }
        next();
      };
    };

    // Routes
    app.get('/health', (req, res) => {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        environment: config.app.env,
        version: config.app.version
      });
    });

    // Config endpoint (sanitized - no secrets exposed)
    app.get('/config', (req, res) => {
      res.json({
        app: {
          name: config.app.name,
          version: config.app.version,
          env: config.app.env,
        },
        features: {
          database: config.database.enabled,
          auth: config.auth.enabled,
          stripe: config.stripe.enabled,
          anthropic: config.anthropic.enabled,
        }
      });
    });

    app.get('/users', 
      strictLimiter,
      authenticateToken,
      [
        query('page').optional().isInt({ min: 1 }).toInt(),
        query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
        query('search').optional().trim().escape()
      ],
      (req, res) => {
        // Validate inputs
        const errors = validationResult(req);
        if (!errors.isEmpty()) {
          return res.status(400).json({ errors: errors.array() });
        }

        const users = [
          { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
          { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
        ];

        // Sanitize output based on user role
        const sanitizedUsers = users.map(user => {
          if (req.user.role !== 'admin') {
            const { email, role, ...userWithoutSensitiveData } = user;
            return userWithoutSensitiveData;
          }
          return user;
        });

        res.json({
          data: sanitizedUsers,
          pagination: {
            page: req.query.page || 1,
            limit: req.query.limit || 10,
            total: users.length
          }
        });
      }
    );

    // 404 handler
    app.use((req, res) => {
      res.status(404).json({ error: 'Not found' });
    });

    // Global error handler
    app.use((err, req, res, next) => {
      // Log error (use proper logging service in production)
      console.error({
        timestamp: new Date().toISOString(),
        error: err.message,
        stack: config.app.env === 'development' ? err.stack : undefined,
        url: req.url,
        method: req.method,
        ip: req.ip
      });

      // Don't expose error details in production
      const isDevelopment = config.app.env === 'development';

      res.status(err.status || 500).json({
        error: {
          message: isDevelopment ? err.message : 'Internal server error',
          ...(isDevelopment && { stack: err.stack })
        }
      });
    });

    // Start server
    const server = app.listen(config.app.port, config.app.host, () => {
      console.log(`✓ Server running on ${config.app.host}:${config.app.port} in ${config.app.env} mode`);
      console.log(`✓ Secrets provider: ${process.env.SECRETS_PROVIDER || 'env'}`);
    });

    // Graceful shutdown
    const gracefulShutdown = (signal) => {
      console.log(`\n${signal} signal received: closing HTTP server`);
      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });

      // Force close after 10 seconds
      setTimeout(() => {
        console.error('Forcing shutdown after timeout');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));

    return server;

  } catch (error) {
    console.error('Failed to initialize application:', error);
    process.exit(1);
  }
}

// Only start if running directly (not being required for tests)
if (require.main === module) {
  initializeApp();
}

module.exports = { app, initializeApp };

