/**
 * Secrets Rotation Script
 * 
 * Automates the rotation of secrets in your secrets manager
 * Use this as part of your security compliance process
 */

const { SecretsManagerClient, UpdateSecretCommand, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const crypto = require('crypto');

const SECRETS_TO_ROTATE = [
  'JWT_SECRET',
  'ENCRYPTION_KEY',
  'API_KEY',
];

async function rotateSecret(secretName, region = 'us-east-1') {
  const client = new SecretsManagerClient({ region });

  try {
    // Get current secret
    console.log(`Fetching current secret: ${secretName}`);
    const getCommand = new GetSecretValueCommand({ SecretId: secretName });
    const currentSecret = await client.send(getCommand);
    const secrets = JSON.parse(currentSecret.SecretString);

    // Generate new values for secrets that should be rotated
    let rotated = false;
    for (const key of SECRETS_TO_ROTATE) {
      if (secrets[key]) {
        console.log(`Rotating: ${key}`);
        secrets[key] = crypto.randomBytes(32).toString('hex');
        rotated = true;
      }
    }

    if (!rotated) {
      console.log('No secrets to rotate');
      return;
    }

    // Update secret
    const updateCommand = new UpdateSecretCommand({
      SecretId: secretName,
      SecretString: JSON.stringify(secrets, null, 2),
    });

    await client.send(updateCommand);
    console.log('✓ Secrets rotated successfully');
    console.log('\n⚠️  IMPORTANT: Restart all application instances to pick up new secrets!');

  } catch (error) {
    console.error('Error rotating secrets:', error.message);
    process.exit(1);
  }
}

// CLI usage
if (require.main === module) {
  const secretName = process.argv[2];
  const region = process.argv[3] || process.env.AWS_REGION || 'us-east-1';

  if (!secretName) {
    console.error('Usage: node rotate-secrets.js <secret-name> [region]');
    console.error('Example: node rotate-secrets.js app-secrets-production us-east-1');
    process.exit(1);
  }

  rotateSecret(secretName, region);
}

module.exports = { rotateSecret };

#!/usr/bin/env node

/**
 * Security Audit Script
 * 
 * Scans for potential security issues including:
 * - Hardcoded secrets
 * - Exposed .env files
 * - Insecure configurations
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Patterns that indicate potential secrets
const SECRET_PATTERNS = [
  /password\s*=\s*['"][^'"]+['"]/gi,
  /api[_-]?key\s*=\s*['"][^'"]+['"]/gi,
  /secret\s*=\s*['"][^'"]+['"]/gi,
  /token\s*=\s*['"][^'"]+['"]/gi,
  /sk-live-[a-zA-Z0-9]+/g,
  /sk-test-[a-zA-Z0-9]+/g,
  /AKIA[0-9A-Z]{16}/g, // AWS Access Key
  /AIza[0-9A-Za-z\-_]{35}/g, // Google API Key
  /sk-ant-[a-zA-Z0-9-]+/g, // Anthropic API Key
  /ghp_[a-zA-Z0-9]{36}/g, // GitHub Personal Access Token
  /postgres:\/\/[^:]+:[^@]+@/g, // Database URL with password
];

const IGNORE_PATHS = [
  'node_modules',
  '.git',
  'dist',
  'build',
  '.next',
  'coverage',
];

class SecurityAuditor {
  constructor() {
    this.findings = [];
    this.errors = [];
  }

  addFinding(severity, category, message, file, line) {
    this.findings.push({
      severity,
      category,
      message,
      file,
      line,
    });
  }

  scanFile(filePath) {
    try {
      const content = fs.readFileSync(filePath, 'utf-8');
      const lines = content.split('\n');

      lines.forEach((line, index) => {
        SECRET_PATTERNS.forEach(pattern => {
          if (pattern.test(line)) {
            this.addFinding(
              'HIGH',
              'Potential Secret',
              `Potential hardcoded secret found: ${line.trim().substring(0, 50)}...`,
              filePath,
              index + 1
            );
          }
        });
      });
    } catch (error) {
      this.errors.push(`Error reading ${filePath}: ${error.message}`);
    }
  }

  scanDirectory(dirPath) {
    try {
      const entries = fs.readdirSync(dirPath, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.join(dirPath, entry.name);

        // Skip ignored paths
        if (IGNORE_PATHS.some(ignored => entry.name === ignored)) {
          continue;
        }

        if (entry.isDirectory()) {
          this.scanDirectory(fullPath);
        } else if (entry.isFile()) {
          // Only scan code files
          const ext = path.extname(entry.name);
          if (['.js', '.ts', '.jsx', '.tsx', '.json', '.env'].includes(ext)) {
            this.scanFile(fullPath);
          }
        }
      }
    } catch (error) {
      this.errors.push(`Error scanning ${dirPath}: ${error.message}`);
    }
  }

  checkGitIgnore() {
    const gitignorePath = path.join(process.cwd(), '.gitignore');

    if (!fs.existsSync(gitignorePath)) {
      this.addFinding(
        'CRITICAL',
        'Missing .gitignore',
        '.gitignore file not found - secrets could be committed!',
        '.gitignore',
        0
      );
      return;
    }

    const gitignoreContent = fs.readFileSync(gitignorePath, 'utf-8');
    const requiredPatterns = ['.env', '.env.local', '.env.*.local', '*.pem', '*.key'];

    for (const pattern of requiredPatterns) {
      if (!gitignoreContent.includes(pattern)) {
        this.addFinding(
          'HIGH',
          'Incomplete .gitignore',
          `Pattern "${pattern}" not found in .gitignore`,
          '.gitignore',
          0
        );
      }
    }
  }

  checkEnvFiles() {
    const envFiles = ['.env', '.env.local', '.env.production', '.env.development'];

    for (const envFile of envFiles) {
      const envPath = path.join(process.cwd(), envFile);

      if (fs.existsSync(envPath)) {
        // Check if it's tracked by git
        try {
          const isTracked = execSync(`git ls-files --error-unmatch ${envFile} 2>/dev/null`, {
            stdio: 'pipe'
          });

          if (isTracked) {
            this.addFinding(
              'CRITICAL',
              'Environment File in Git',
              `${envFile} is tracked by git! This may expose secrets.`,
              envFile,
              0
            );
          }
        } catch (error) {
          // File not tracked (good)
        }

        // Check for live/production keys in non-production files
        if (!envFile.includes('production')) {
          const content = fs.readFileSync(envPath, 'utf-8');
          if (content.includes('sk-live-') || content.includes('prod') || content.includes('PROD')) {
            this.addFinding(
              'CRITICAL',
              'Production Credentials in Non-Production File',
              `${envFile} appears to contain production credentials!`,
              envFile,
              0
            );
          }
        }
      }
    }
  }

  checkDependencies() {
    const packagePath = path.join(process.cwd(), 'package.json');

    if (!fs.existsSync(packagePath)) {
      return;
    }

    try {
      // Run npm audit
      const auditResult = execSync('npm audit --json', { stdio: 'pipe' }).toString();
      const audit = JSON.parse(auditResult);

      if (audit.metadata && audit.metadata.vulnerabilities) {
        const vulns = audit.metadata.vulnerabilities;
        const total = vulns.critical + vulns.high + vulns.moderate + vulns.low;

        if (total > 0) {
          this.addFinding(
            'HIGH',
            'Vulnerable Dependencies',
            `Found ${total} vulnerabilities (${vulns.critical} critical, ${vulns.high} high)`,
            'package.json',
            0
          );
        }
      }
    } catch (error) {
      // npm audit returns non-zero exit code when vulnerabilities found
      this.addFinding(
        'MEDIUM',
        'Dependency Check',
        'Run "npm audit" to check for vulnerable dependencies',
        'package.json',
        0
      );
    }
  }

  generateReport() {
    console.log('\n═══════════════════════════════════════════');
    console.log('         SECURITY AUDIT REPORT');
    console.log('═══════════════════════════════════════════\n');

    const criticalFindings = this.findings.filter(f => f.severity === 'CRITICAL');
    const highFindings = this.findings.filter(f => f.severity === 'HIGH');
    const mediumFindings = this.findings.filter(f => f.severity === 'MEDIUM');

    console.log(`🔴 Critical: ${criticalFindings.length}`);
    console.log(`🟠 High: ${highFindings.length}`);
    console.log(`🟡 Medium: ${mediumFindings.length}`);
    console.log(`\nTotal Findings: ${this.findings.length}\n`);

    if (this.findings.length === 0) {
      console.log('✅ No security issues found!\n');
      return 0;
    }

    // Group by severity
    ['CRITICAL', 'HIGH', 'MEDIUM'].forEach(severity => {
      const findings = this.findings.filter(f => f.severity === severity);

      if (findings.length > 0) {
        const icon = severity === 'CRITICAL' ? '🔴' : severity === 'HIGH' ? '🟠' : '🟡';
        console.log(`\n${icon} ${severity} SEVERITY\n${'─'.repeat(40)}`);

        findings.forEach((finding, index) => {
          console.log(`\n${index + 1}. [${finding.category}]`);
          console.log(`   File: ${finding.file}${finding.line ? `:${finding.line}` : ''}`);
          console.log(`   ${finding.message}`);
        });
      }
    });

    if (this.errors.length > 0) {
      console.log('\n\n⚠️  ERRORS\n' + '─'.repeat(40));
      this.errors.forEach(error => console.log(`  ${error}`));
    }

    console.log('\n═══════════════════════════════════════════\n');

    // Return exit code based on findings
    return criticalFindings.length > 0 ? 2 : highFindings.length > 0 ? 1 : 0;
  }

  run() {
    console.log('Starting security audit...\n');

    console.log('✓ Checking .gitignore...');
    this.checkGitIgnore();

    console.log('✓ Checking environment files...');
    this.checkEnvFiles();

    console.log('✓ Scanning for hardcoded secrets...');
    this.scanDirectory(process.cwd());

    console.log('✓ Checking dependencies...');
    this.checkDependencies();

    return this.generateReport();
  }
}

// Run audit
if (require.main === module) {
  const auditor = new SecurityAuditor();
  const exitCode = auditor.run();
  process.exit(exitCode);
}

module.exports = SecurityAuditor;

