];

function detectSecretLeakage(req, res, next) {
  // Override res.json to check for secret leakage
  const originalJson = res.json.bind(res);

  res.json = (data) => {
    const stringData = JSON.stringify(data);

    // Check for canary tokens
    for (const pattern of CANARY_PATTERNS) {
      if (pattern.test(stringData)) {
        console.error('🚨 ALERT: Canary token detected in response!', {
          timestamp: new Date().toISOString(),
          path: req.path,
          method: req.method,
          ip: req.ip,
