- Denial of Service (DoS)
- API abuse
- Resource exhaustion

**Remediation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.'
});

app.use(limiter);
```

---

#### 3. **Missing Security Headers** (OWASP A05:2021 - Security Misconfiguration)
**Risk:** Vulnerable to:
- Cross-Site Scripting (XSS)
- Clickjacking
- MIME type sniffing attacks
- Man-in-the-middle attacks

**Remediation:**
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true
  }
}));
```

---

#### 4. **No HTTPS Enforcement**
**Risk:** Data transmitted in plain text can be intercepted.

**Remediation:**
```javascript
// Force HTTPS in production
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, `https://${req.headers.host}${req.url}`);
  }
  next();
});
```

---

### High Severity Issues

#### 5. **No Input Validation** (OWASP A03:2021 - Injection)
**Risk:** Vulnerable to injection attacks if query parameters or POST data are processed.

**Remediation:**
```javascript
const validator = require('validator');
const { body, query, param, validationResult } = require('express-validator');

// Validation middleware
const validateUserId = [
  param('id').isInt({ min: 1 }).withMessage('Invalid user ID'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
];

app.get('/users/:id', validateUserId, (req, res) => {
  // Safe to use req.params.id
});
```

---

#### 6. **No Error Handling** (OWASP A04:2021 - Insecure Design)
**Risk:** Unhandled errors may expose:
- Stack traces
- Internal system information
- Database structure
- File paths

**Remediation:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack); // Log for debugging

  // Don't expose internal errors to clients
  res.status(err.statusCode || 500).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An error occurred' 
      : err.message
  });
});

// Async error wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};
```

---

### Medium Severity Issues

#### 7. **No CORS Configuration** (OWASP A05:2021 - Security Misconfiguration)
**Risk:** Unrestricted cross-origin requests could allow unauthorized access.

**Remediation:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: ['https://yourdomain.com', 'https://app.yourdomain.com'],
  methods: ['GET', 'POST'],
  credentials: true,
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));
```

---

#### 8. **No Request Size Limits**
**Risk:** Large payloads could cause memory exhaustion.

**Remediation:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

---

#### 9. **No Logging/Monitoring** (OWASP A09:2021 - Security Logging Failures)
**Risk:** Cannot detect or respond to security incidents.

**Remediation:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// HTTP request logging
app.use(morgan('combined'));

// Application logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Log security events
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });
  next();
});
```

---

#### 10. **Hardcoded Sensitive Data**
**Risk:** User data should be in a database with proper access controls.

**Remediation:**
```javascript
// Use environment variables for configuration
require('dotenv').config();

// Use proper database with parameterized queries
const db = require('./db'); // Using ORM like Sequelize, Prisma, etc.

app.get('/users', authenticateUser, async (req, res) => {
  try {
    const users = await db.User.findAll({
      attributes: ['id', 'name', 'email'] // Explicit field selection
    });
    res.json(users);
  } catch (error) {
    next(error);
  }
});
```

