// Secure Express Application - Best Practices Implementation
// Author: Security Review
// Date: 2024

const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS configuration
const morgan = require('morgan'); // Logging
const { body, query, validationResult } = require('express-validator'); // Input validation
require('dotenv').config(); // Environment variables

const app = express();

// ============================================
// 1. TRUST PROXY (if behind reverse proxy)
// ============================================
app.set('trust proxy', 1);

// ============================================
// 2. SECURITY HEADERS (Helmet)
// ============================================
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: 'same-origin' },
  noSniff: true,
  frameguard: { action: 'deny' },
}));

// ============================================
// 3. CORS CONFIGURATION
// ============================================
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['https://yourdomain.com'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// ============================================
// 4. BODY PARSING (with limits)
// ============================================
app.use(express.json({ 
  limit: '10kb', // Prevent large payload attacks
  strict: true   // Only accept arrays and objects
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// ============================================
// 5. REQUEST LOGGING (Don't log sensitive data)
// ============================================
app.use(morgan('combined', {
  skip: (req, res) => res.statusCode < 400,
  stream: {
    write: (message) => {
      // In production, send to proper logging service
      console.log(message.trim());
    }
  }
}));

// ============================================
// 6. RATE LIMITING
// ============================================
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  // Store in Redis for production
  // store: new RedisStore({ client: redisClient })
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests, please try again later.'
});

app.use('/api/', generalLimiter);

// ============================================
// 7. AUTHENTICATION MIDDLEWARE
// ============================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Access denied. No token provided.' 
    });
  }

  try {
    // In production, use proper JWT verification
    // const jwt = require('jsonwebtoken');
    // const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // req.user = decoded;

    // Placeholder for demonstration
    if (token === process.env.API_KEY) {
      req.user = { id: 1, role: 'admin' };
      next();
    } else {
      return res.status(403).json({ 
        error: 'Invalid or expired token.' 
      });
    }
  } catch (error) {
    return res.status(403).json({ 
      error: 'Invalid or expired token.' 
    });
  }
};

// ============================================
// 8. AUTHORIZATION MIDDLEWARE
// ============================================
const authorizeRoles = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Access forbidden. Insufficient permissions.' 
      });
    }
    next();
  };
};

// ============================================
// 9. INPUT VALIDATION MIDDLEWARE
// ============================================
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Invalid input', 
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// 10. SANITIZE OUTPUT
// ============================================
const sanitizeUser = (user) => {
  // Remove sensitive fields
  const { password, ssn, creditCard, ...safeUser } = user;
  return safeUser;
};

// ============================================
// ROUTES
// ============================================

// Public health check endpoint (no auth required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Protected users endpoint with authentication and rate limiting
app.get('/api/users', 
  strictLimiter,
  authenticateToken,
  authorizeRoles('admin', 'user'),
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('search')
      .optional()
      .trim()
      .escape()
      .isLength({ max: 100 })
      .withMessage('Search query too long')
  ],
  validateRequest,
  (req, res) => {
    try {
      // In production, fetch from database with parameterized queries
      const users = [
        { 
          id: 1, 
          name: 'Alice', 
          email: 'alice@example.com',
          role: 'admin',
          password: 'hashed_password_1' // Would be removed by sanitization
        },
        { 
          id: 2, 
          name: 'Bob', 
          email: 'bob@example.com',
          role: 'user',
          password: 'hashed_password_2'
        },
      ];

      // Sanitize output
      const safeUsers = users.map(sanitizeUser);

      // Implement pagination
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;

      const paginatedUsers = safeUsers.slice(startIndex, endIndex);

      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: safeUsers.length,
          totalPages: Math.ceil(safeUsers.length / limit)
        }
      });
    } catch (error) {
      // Don't leak error details
      console.error('Error fetching users:', error);
      res.status(500).json({ 
        error: 'Internal server error. Please try again later.' 
      });
    }
  }
);

// Get specific user by ID
app.get('/api/users/:id',
  authenticateToken,
  authorizeRoles('admin', 'user'),
  [
    query('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
  ],
  validateRequest,
  (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // In production, use parameterized queries to prevent SQL injection
      // const user = await db.query('SELECT * FROM users WHERE id = $1', [userId]);

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found' 
        });
      }

      // Check if user can access this resource
      if (req.user.role !== 'admin' && req.user.id !== userId) {
        return res.status(403).json({ 
          error: 'Access forbidden. You can only access your own data.' 
        });
      }

      res.json({
        success: true,
        data: sanitizeUser(user)
      });
    } catch (error) {
      console.error('Error fetching user:', error);
      res.status(500).json({ 
        error: 'Internal server error. Please try again later.' 
      });
    }
  }
);

// ============================================
// 404 HANDLER
// ============================================
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Route not found' 
  });
});

// ============================================
// GLOBAL ERROR HANDLER
// ============================================
app.use((err, req, res, next) => {
  // Log error for monitoring
  console.error('Unhandled error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================
// HTTPS ENFORCEMENT (if not behind proxy)
// ============================================
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// ============================================
// SERVER STARTUP
// ============================================
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

