## 🔐 Secure Secrets Loading Pattern

```javascript
// config/secrets.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.secretsClient = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    try {
      const data = await this.secretsClient.getSecretValue({
        SecretId: secretName
      }).promise();

      const secretValue = data.SecretString 
        ? JSON.parse(data.SecretString) 
        : data.SecretBinary;

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error('Failed to load application secrets');
    }
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new SecretsManager();
```

