        // to prevent user enumeration
        res.status(401).json({ 
          error: 'Invalid credentials' 
        });
      }
    } catch (error) {
      next(error);
    }
  }
);

// Users endpoint - Protected with authentication
app.get('/api/users', 
  authenticateToken, // Require authentication
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
  ],
  validate,
  (req, res) => {
    try {
