        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Get specific user - Protected and validated
app.get('/api/users/:id',
  authenticateToken,
  [
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer'),
  ],
  validate,
  (req, res, next) => {
    try {
