## 4. Authorization Testing

### Test Role-Based Access Control

```javascript
describe('Authorization', () => {
  test('admin can access all user data', async () => {
    const token = generateToken({ id: 1, role: 'admin' });

    const response = await request(app)
      .get('/api/users')
      .set('Authorization', `Bearer ${token}`)
      .expect(200);

    expect(response.body.data[0].email).toBeDefined();
  });

  test('regular user cannot access other user emails', async () => {
    const token = generateToken({ id: 1, role: 'user' });

    const response = await request(app)
      .get('/api/users')
      .set('Authorization', `Bearer ${token}`)
      .expect(200);

    // Email should be filtered out for non-admin
    expect(response.body.data[0].email).toBeUndefined();
  });

  test('user cannot access other user details', async () => {
    const token = generateToken({ id: 1, role: 'user' });

    // Try to access user ID 2
    const response = await request(app)
      .get('/api/users/2')
      .set('Authorization', `Bearer ${token}`)
      .expect(403);

    expect(response.body.error).toContain('Access denied');
  });
});
```

