## 7. Rate Limiting Testing

### Test Rate Limits

```bash
# Bash script to test rate limiting
for i in {1..101}; do
  echo "Request $i"
  curl -w "\nStatus: %{http_code}\n" http://localhost:3000/api/users \
    -H "Authorization: Bearer $TOKEN"
  sleep 0.1
done

# Expected: First 100 requests succeed, 101st returns 429 Too Many Requests
```

### Automated Test

```javascript
describe('Rate Limiting', () => {
  test('should rate limit after max requests', async () => {
    const token = generateToken({ id: 1, role: 'admin' });

    // Make 101 requests
    const requests = [];
    for (let i = 0; i < 101; i++) {
      requests.push(
        request(app)
          .get('/api/users')
          .set('Authorization', `Bearer ${token}`)
      );
    }

    const responses = await Promise.all(requests);

    // Check that some requests were rate limited
    const rateLimited = responses.filter(r => r.status === 429);
    expect(rateLimited.length).toBeGreaterThan(0);
  });

  test('should have stricter limits on auth endpoints', async () => {
    const requests = [];
    for (let i = 0; i < 21; i++) {
      requests.push(
        request(app)
          .post('/api/login')
          .send({
            email: 'test@example.com',
            password: 'wrong'
          })
      );
    }

    const responses = await Promise.all(requests);
    const rateLimited = responses.filter(r => r.status === 429);
    expect(rateLimited.length).toBeGreaterThan(0);
  });
});
```

