# Security Quick Reference Guide

## 🚨 Critical Security Patterns

### ✅ DO's

#### Authentication
```javascript
// ✅ GOOD: JWT with proper configuration
const jwt = require('jsonwebtoken');
const token = jwt.sign(
  { id: user.id, role: user.role },
  process.env.JWT_SECRET,
  { expiresIn: '1h', algorithm: 'HS256' }
);
```

#### Password Hashing
```javascript
// ✅ GOOD: Use bcrypt with proper salt rounds
const bcrypt = require('bcrypt');
const hashedPassword = await bcrypt.hash(password, 12);
const isValid = await bcrypt.compare(password, hashedPassword);
```

#### Input Validation
```javascript
// ✅ GOOD: Validate and sanitize all inputs
const { body, validationResult } = require('express-validator');

app.post('/api/users',
  [
    body('email').isEmail().normalizeEmail(),
    body('name').trim().escape().isLength({ min: 2, max: 50 }),
    body('age').optional().isInt({ min: 0, max: 120 })
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process validated data
  }
);
```

#### Database Queries
```javascript
// ✅ GOOD: Parameterized queries
const result = await db.query(
  'SELECT * FROM users WHERE email = $1',
  [email]
);

// ✅ GOOD: ORM with proper escaping
const user = await User.findOne({ where: { email } });
```

#### Security Headers
```javascript
// ✅ GOOD: Use Helmet
const helmet = require('helmet');
app.use(helmet());
```

#### Rate Limiting
```javascript
// ✅ GOOD: Implement rate limiting
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use('/api/', limiter);
```

#### CORS
```javascript
// ✅ GOOD: Whitelist specific origins
const cors = require('cors');
app.use(cors({
  origin: ['https://yourdomain.com'],
  credentials: true
}));
```

#### Error Handling
```javascript
// ✅ GOOD: Generic error messages
app.use((err, req, res, next) => {
  logger.error(err.stack); // Log internally
  res.status(500).json({ error: 'Internal server error' }); // Generic message
});
```

#### Secrets Management
```javascript
// ✅ GOOD: Use environment variables
require('dotenv').config();
const secret = process.env.JWT_SECRET;
if (!secret) throw new Error('JWT_SECRET required');
```

---

### ❌ DON'Ts

#### Authentication
```javascript
// ❌ BAD: No authentication
app.get('/api/users', (req, res) => {
  res.json(users); // Anyone can access
});

// ❌ BAD: Weak token generation
const token = Math.random().toString(36);

// ❌ BAD: Hardcoded credentials
if (username === 'admin' && password === 'password123') {
  // Grant access
}
```

#### Password Storage
```javascript
// ❌ BAD: Plain text passwords
