## Issue #1: No Authentication

### ❌ VULNERABLE (Original)
```javascript
// app.js - Lines 13-18
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```
**Problem:** Anyone can access user data including emails (PII)

### ✅ SECURE (Fixed)
```javascript
// app.secure.js - Lines 211-255
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Access denied. No token provided.' 
    });
  }

  try {
    const verified = jwt.verify(token, JWT_SECRET);
    req.user = verified;
    next();
  } catch (err) {
    console.error(`[SECURITY] Failed authentication attempt from ${req.ip}`);
    return res.status(403).json({ 
      error: 'Invalid or expired token.' 
    });
  }
};

app.get('/api/users', 
  authenticateToken, // ← Authentication required
  [
    query('page').optional().isInt({ min: 1 }),
    query('limit').optional().isInt({ min: 1, max: 100 }),
  ],
  validate,
  (req, res) => {
    console.log(`[AUDIT] User ${req.user.id} accessed /api/users`);

    // Implement role-based access control
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter sensitive data based on user role
    const sanitizedUsers = users.map(user => {
      if (req.user.role === 'admin') {
        return user;
      } else {
        return { id: user.id, name: user.name }; // No email for non-admins
      }
    });

    res.json({ data: sanitizedUsers });
  }
);
```
**Fixed:** JWT authentication + role-based authorization + audit logging

