**Problem:** Passwords stored in plain text

### ✅ SECURE (Fixed)
```javascript
const bcrypt = require('bcrypt');

app.post('/api/register', validate, async (req, res) => {
  const { email, password } = req.body;

  // Hash with 12 rounds
  const hashedPassword = await bcrypt.hash(password, 12);

  const user = {
    email,
    password: hashedPassword // Hashed!
  };

  await db.insert(user);
  res.status(201).json({ message: 'User created' });
});

// Login verification
app.post('/api/login', validate, async (req, res) => {
  const user = await db.findByEmail(req.body.email);

  // Compare with bcrypt
  const isValid = await bcrypt.compare(req.body.password, user.password);

  if (isValid) {
    const token = jwt.sign({ id: user.id }, JWT_SECRET, { expiresIn: '1h' });
    res.json({ token });
  } else {
    res.status(401).json({ error: 'Invalid credentials' });
  }
});
```
**Fixed:** bcrypt hashing with 12 rounds (industry standard)

