const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================
// 1. SECURITY HEADERS (Helmet)
// ============================================
// Protects against: XSS, Clickjacking, MIME-sniffing
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: {
    action: 'deny'
  },
  noSniff: true,
  xssFilter: true
}));

// ============================================
// 2. CORS CONFIGURATION
// ============================================
// Restrict cross-origin requests to trusted domains only
const corsOptions = {
  origin: function (origin, callback) {
    const whitelist = [
      'https://yourdomain.com',
      'https://app.yourdomain.com'
    ];

    // Allow requests with no origin (mobile apps, Postman, etc.)
    if (!origin || whitelist.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));

// ============================================
// 3. REQUEST PARSING & SIZE LIMITS
// ============================================
// Prevent payload-based DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// 4. RATE LIMITING
// ============================================
// Prevent brute force and DoS attacks
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  // Store in Redis for production (not memory)
  // store: new RedisStore({ client: redisClient })
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests, please try again later.'
});

app.use('/api/', generalLimiter);

// ============================================
// 5. LOGGING & MONITORING
// ============================================
// Security event logging
morgan.token('user-id', (req) => req.user ? req.user.id : 'anonymous');

app.use(morgan(':remote-addr :user-id :method :url :status :response-time ms', {
  stream: {
    write: (message) => {
      // In production, send to centralized logging (ELK, Splunk, etc.)
      console.log(`[ACCESS LOG] ${message.trim()}`);
    }
  }
}));

// ============================================
// 6. AUTHENTICATION MIDDLEWARE
// ============================================
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_THIS_IN_PRODUCTION';
const JWT_EXPIRES_IN = '1h';

// Middleware to verify JWT tokens
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ 
      error: 'Access denied. No token provided.' 
    });
  }

  try {
    const verified = jwt.verify(token, JWT_SECRET);
    req.user = verified;
    next();
  } catch (err) {
    // Log failed authentication attempts
    console.error(`[SECURITY] Failed authentication attempt from ${req.ip}`);
    return res.status(403).json({ 
      error: 'Invalid or expired token.' 
    });
  }
};

// ============================================
// 7. INPUT VALIDATION & SANITIZATION
// ============================================
// Middleware to check validation results
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Invalid input',
      details: errors.array() 
    });
  }
  next();
};

// ============================================
// 8. ERROR HANDLING MIDDLEWARE
// ============================================
// Global error handler (must be last)
const errorHandler = (err, req, res, next) => {
  // Log error details for monitoring
  console.error(`[ERROR] ${err.stack}`);

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
};

