/**
 * Secure Secrets Management
 * 
 * Multi-provider secrets manager with fallback support
 * - Production: AWS Secrets Manager, Azure Key Vault, or HashiCorp Vault
 * - Development: .env files (gitignored)
 * - Automatic validation and fail-secure behavior
 */

const crypto = require('crypto');

class SecretsManager {
  constructor(options = {}) {
    this.provider = options.provider || process.env.SECRETS_PROVIDER || 'env';
    this.environment = process.env.NODE_ENV || 'development';
    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 300000; // 5 minutes default
    this.auditLog = options.auditLog !== false; // Enabled by default

    // Required secrets that must be present
    this.requiredSecrets = [
      'JWT_SECRET',
      'SESSION_SECRET',
    ];

    // Secret strength requirements
    this.secretRequirements = {
      JWT_SECRET: { minLength: 32, pattern: /^[a-f0-9]{64,}$/i },
      SESSION_SECRET: { minLength: 32, pattern: /^[a-f0-9]{64,}$/i },
      DB_PASSWORD: { minLength: 16 },
      ENCRYPTION_KEY: { minLength: 32, pattern: /^[a-f0-9]{64,}$/i },
    };
  }

  /**
   * Initialize secrets manager and validate configuration
   */
  async initialize() {
    console.log(`[SECRETS] Initializing secrets manager (provider: ${this.provider})`);

    try {
      // Load provider-specific implementation
      switch (this.provider) {
        case 'aws':
          this.providerImpl = require('./secrets-aws');
          await this.providerImpl.initialize();
          break;
        case 'azure':
          this.providerImpl = require('./secrets-azure');
          await this.providerImpl.initialize();
          break;
        case 'vault':
          this.providerImpl = require('./secrets-vault');
          await this.providerImpl.initialize();
          break;
        case 'gcp':
          this.providerImpl = require('./secrets-gcp');
          await this.providerImpl.initialize();
          break;
        case 'env':
          // Load from environment variables (requires dotenv)
          require('dotenv').config();
          this.providerImpl = {
            getSecret: async (name) => process.env[name]
          };
          break;
        default:
          throw new Error(`Unknown secrets provider: ${this.provider}`);
      }

      // Validate all required secrets are present
      await this.validateRequiredSecrets();

      // Validate secret strength
      await this.validateSecretStrength();

      console.log('[SECRETS] Initialization complete');
      return true;
    } catch (error) {
      console.error('[SECRETS] FATAL: Failed to initialize secrets manager', error);

      if (this.environment === 'production') {
        // Fail-secure: don't start application without secrets
        process.exit(1);
      } else {
        console.warn('[SECRETS] WARNING: Running in development mode with potential issues');
        return false;
      }
    }
  }

  /**
   * Get a secret value
   * @param {string} name - Secret name
   * @param {object} options - Options (useCache, required)
   * @returns {Promise<string>} Secret value
   */
  async getSecret(name, options = {}) {
    const { useCache = true, required = false } = options;

    // Check cache first
    if (useCache && this.cache.has(name)) {
      const cached = this.cache.get(name);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        if (this.auditLog) {
          this.logSecretAccess(name, 'cache-hit');
        }
        return cached.value;
      } else {
        // Cache expired
        this.cache.delete(name);
      }
    }

    try {
      // Fetch from provider
      const value = await this.providerImpl.getSecret(name);

      if (!value && required) {
        throw new Error(`Required secret '${name}' is not set`);
      }

      // Cache the value
      if (useCache && value) {
        this.cache.set(name, {
          value,
          timestamp: Date.now()
        });
      }

      if (this.auditLog && value) {
        this.logSecretAccess(name, 'retrieved');
      }

      return value;
    } catch (error) {
      console.error(`[SECRETS] Failed to get secret '${name}':`, error.message);

      if (required) {
        throw error;
      }

      return null;
    }
  }

  /**
   * Get multiple secrets at once
   * @param {string[]} names - Array of secret names
   * @returns {Promise<Object>} Object with secret name-value pairs
   */
  async getSecrets(names) {
    const secrets = {};

    await Promise.all(
      names.map(async (name) => {
        secrets[name] = await this.getSecret(name);
      })
    );

    return secrets;
  }

  /**
   * Validate that all required secrets are present
   */
  async validateRequiredSecrets() {
    console.log('[SECRETS] Validating required secrets...');

    const missing = [];

    for (const name of this.requiredSecrets) {
      const value = await this.getSecret(name, { useCache: false });
      if (!value) {
        missing.push(name);
      }
    }

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}\n` +
        `Please configure these secrets in your secrets manager or .env file`
      );
    }

    console.log(`[SECRETS] ✓ All ${this.requiredSecrets.length} required secrets are present`);
  }

  /**
   * Validate secret strength (length, complexity)
   */
  async validateSecretStrength() {
    console.log('[SECRETS] Validating secret strength...');

    const weak = [];

    for (const [name, requirements] of Object.entries(this.secretRequirements)) {
      const value = await this.getSecret(name, { useCache: false });

      if (!value) continue; // Skip if not set (will be caught by required check)

      // Check minimum length
      if (requirements.minLength && value.length < requirements.minLength) {
        weak.push(`${name} (too short: ${value.length} < ${requirements.minLength})`);
      }

      // Check pattern
      if (requirements.pattern && !requirements.pattern.test(value)) {
        weak.push(`${name} (doesn't match required pattern)`);
      }
    }

    if (weak.length > 0) {
      const error = `Weak secrets detected:\n${weak.map(w => `  - ${w}`).join('\n')}`;

      if (this.environment === 'production') {
        throw new Error(error);
      } else {
        console.warn(`[SECRETS] WARNING: ${error}`);
      }
    } else {
      console.log('[SECRETS] ✓ All secrets meet strength requirements');
    }
  }

  /**
   * Clear secret cache (useful after rotation)
   */
  clearCache() {
    const count = this.cache.size;
    this.cache.clear();
    console.log(`[SECRETS] Cleared ${count} cached secrets`);
  }

  /**
   * Clear specific secret from cache
   */
  clearSecret(name) {
    if (this.cache.has(name)) {
      this.cache.delete(name);
      console.log(`[SECRETS] Cleared cached secret: ${name}`);
    }
  }

  /**
   * Log secret access for audit trail
   */
  logSecretAccess(name, action) {
    // IMPORTANT: Never log the secret VALUE, only the name and action
    const logEntry = {
      timestamp: new Date().toISOString(),
      action,
      secret: name,
      provider: this.provider,
      environment: this.environment,
      // Don't log: value, secret contents, etc.
    };

    console.log(`[SECRETS-AUDIT] ${JSON.stringify(logEntry)}`);

    // In production, send to centralized audit log (SIEM, CloudWatch, etc.)
    // Example: await auditLogger.log(logEntry);
  }

  /**
   * Generate a new strong secret
   * @param {number} bytes - Number of bytes (will be hex-encoded to 2x length)
   * @returns {string} Generated secret
   */
  static generateSecret(bytes = 32) {
    return crypto.randomBytes(bytes).toString('hex');
  }

  /**
   * Test connection to secrets provider
   */
  async healthCheck() {
    try {
      // Try to fetch a test secret or any secret
      await this.getSecret(this.requiredSecrets[0], { useCache: false });
      return { healthy: true, provider: this.provider };
    } catch (error) {
      return { 
        healthy: false, 
        provider: this.provider, 
        error: error.message 
      };
    }
  }
}

// Singleton instance
let instance = null;

/**
 * Get or create secrets manager instance
 */
function getSecretsManager(options = {}) {
  if (!instance) {
    instance = new SecretsManager(options);
  }
  return instance;
}

/**
 * Initialize secrets manager (must be called before app starts)
 */
async function initializeSecrets(options = {}) {
  const manager = getSecretsManager(options);
  await manager.initialize();
  return manager;
}

module.exports = {
  SecretsManager,
  getSecretsManager,
  initializeSecrets,
  generateSecret: SecretsManager.generateSecret
};

/**
 * AWS Secrets Manager Provider
 * 
 * Production-ready integration with AWS Secrets Manager
 * - Automatic secret rotation support
 * - Error handling and retries
 * - IAM role-based authentication
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class AWSSecretsProvider {
  constructor(options = {}) {
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.prefix = options.prefix || process.env.SECRETS_PREFIX || 'myapp';
    this.client = null;
    this.maxRetries = options.maxRetries || 3;
    this.retryDelay = options.retryDelay || 1000;
  }

  /**
   * Initialize AWS Secrets Manager client
   */
  async initialize() {
    console.log(`[AWS-SECRETS] Initializing AWS Secrets Manager (region: ${this.region})`);

    try {
      this.client = new SecretsManagerClient({
        region: this.region,
        maxAttempts: this.maxRetries,
      });

      // Test connection
      await this.testConnection();

      console.log('[AWS-SECRETS] Successfully connected to AWS Secrets Manager');
    } catch (error) {
      console.error('[AWS-SECRETS] Failed to initialize:', error.message);
      throw error;
    }
  }

  /**
   * Get a secret from AWS Secrets Manager
   * @param {string} name - Secret name (without prefix)
   * @returns {Promise<string>} Secret value
   */
  async getSecret(name) {
    if (!this.client) {
      throw new Error('AWS Secrets Manager client not initialized');
    }

    // Build full secret name with prefix and environment
    const secretName = this.buildSecretName(name);

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
      });

      const response = await this.client.send(command);

      // Secrets can be stored as string or binary
      if (response.SecretString) {
        // Check if it's JSON
        try {
          const parsed = JSON.parse(response.SecretString);
          // If JSON, return the 'value' field or the whole object
          return parsed.value || response.SecretString;
        } catch {
          // Not JSON, return as-is
          return response.SecretString;
        }
      } else if (response.SecretBinary) {
        return Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      return null;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        console.warn(`[AWS-SECRETS] Secret not found: ${secretName}`);
        return null;
      }

      console.error(`[AWS-SECRETS] Error fetching secret '${secretName}':`, error.message);
      throw error;
    }
  }

  /**
   * Get multiple secrets in a batch
   * @param {string[]} names - Array of secret names
   * @returns {Promise<Object>} Object with secret name-value pairs
   */
  async getSecrets(names) {
    const secrets = {};

    // AWS Secrets Manager doesn't have batch API, so we fetch in parallel
    await Promise.all(
      names.map(async (name) => {
        try {
          secrets[name] = await this.getSecret(name);
        } catch (error) {
          console.error(`[AWS-SECRETS] Failed to fetch ${name}:`, error.message);
          secrets[name] = null;
        }
      })
    );

    return secrets;
  }

  /**
   * Build full secret name with prefix and environment
   */
  buildSecretName(name) {
    const env = process.env.NODE_ENV || 'development';
    return `${this.prefix}/${env}/${name}`;
  }

  /**
   * Test connection to AWS Secrets Manager
   */
  async testConnection() {
    try {
      // Try to list secrets (will fail if no IAM permissions)
      const command = new GetSecretValueCommand({
        SecretId: `${this.prefix}/test`,
      });

      await this.client.send(command);
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        // This is OK - means we can connect but secret doesn't exist
        return true;
      }
      throw error;
    }
  }

  /**
   * Create or update a secret (for setup/rotation)
   */
  async putSecret(name, value) {
    const { CreateSecretCommand, UpdateSecretCommand } = require('@aws-sdk/client-secrets-manager');

    const secretName = this.buildSecretName(name);

    try {
      // Try to update first
      const updateCommand = new UpdateSecretCommand({
        SecretId: secretName,
        SecretString: value,
      });

      await this.client.send(updateCommand);
      console.log(`[AWS-SECRETS] Updated secret: ${secretName}`);
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        // Secret doesn't exist, create it
        const createCommand = new CreateSecretCommand({
          Name: secretName,
          SecretString: value,
          Description: `Secret for ${name}`,
        });

        await this.client.send(createCommand);
        console.log(`[AWS-SECRETS] Created secret: ${secretName}`);
      } else {
        throw error;
      }
    }
  }

  /**
   * Enable automatic rotation for a secret
   */
  async enableRotation(name, rotationLambdaArn, rotationDays = 30) {
    const { RotateSecretCommand } = require('@aws-sdk/client-secrets-manager');

    const secretName = this.buildSecretName(name);

    const command = new RotateSecretCommand({
      SecretId: secretName,
      RotationLambdaARN: rotationLambdaArn,
      RotationRules: {
        AutomaticallyAfterDays: rotationDays,
      },
    });

    await this.client.send(command);
    console.log(`[AWS-SECRETS] Enabled rotation for ${secretName} (every ${rotationDays} days)`);
  }
}

