/**
 * HashiCorp Vault Provider
 * 
 * Enterprise-grade secrets management with Vault
 * - Dynamic secret generation
 * - Automatic lease renewal
 * - High availability
 * - Comprehensive audit logging
 */

const vault = require('node-vault');

class VaultSecretsProvider {
  constructor(options = {}) {
    this.endpoint = options.endpoint || process.env.VAULT_ADDR || 'http://127.0.0.1:8200';
    this.token = options.token || process.env.VAULT_TOKEN;
    this.mountPath = options.mountPath || process.env.VAULT_MOUNT_PATH || 'secret';
    this.prefix = options.prefix || process.env.SECRETS_PREFIX || 'myapp';
    this.client = null;
    this.leases = new Map(); // Track leases for renewal
  }

  /**
   * Initialize Vault client
   */
  async initialize() {
    console.log(`[VAULT] Initializing Vault client (endpoint: ${this.endpoint})`);

    try {
      // Initialize Vault client
      this.client = vault({
        apiVersion: 'v1',
        endpoint: this.endpoint,
        token: this.token,
      });

      // Test connection and authentication
      await this.testConnection();

      // Start lease renewal background task
      this.startLeaseRenewal();

      console.log('[VAULT] Successfully connected to Vault');
    } catch (error) {
      console.error('[VAULT] Failed to initialize:', error.message);
      throw error;
    }
  }

  /**
   * Get a secret from Vault
   * @param {string} name - Secret name
   * @returns {Promise<string>} Secret value
   */
  async getSecret(name) {
    if (!this.client) {
      throw new Error('Vault client not initialized');
    }

    const path = this.buildSecretPath(name);

    try {
      // KV v2 uses 'data' wrapper
      const response = await this.client.read(path);

      if (!response || !response.data) {
        return null;
      }

      // KV v2 stores data in data.data
      const data = response.data.data || response.data;

      // Track lease if present (for dynamic secrets)
      if (response.lease_id) {
        this.leases.set(name, {
          lease_id: response.lease_id,
          lease_duration: response.lease_duration,
          renewable: response.renewable,
          path: path,
        });
      }

      // Return the 'value' field or the first field if only one exists
      if (data.value) {
        return data.value;
      } else if (Object.keys(data).length === 1) {
        return data[Object.keys(data)[0]];
      }

      // Return entire data object if multiple fields
      return JSON.stringify(data);
    } catch (error) {
      if (error.response && error.response.statusCode === 404) {
        console.warn(`[VAULT] Secret not found: ${path}`);
        return null;
      }

      console.error(`[VAULT] Error fetching secret '${path}':`, error.message);
      throw error;
    }
  }

  /**
   * Put a secret into Vault
   */
  async putSecret(name, value) {
    const path = this.buildSecretPath(name);

    try {
      await this.client.write(path, {
        data: { value },
      });

      console.log(`[VAULT] Wrote secret: ${path}`);
    } catch (error) {
      console.error(`[VAULT] Error writing secret '${path}':`, error.message);
      throw error;
    }
  }

  /**
   * Build full secret path
   */
  buildSecretPath(name) {
    const env = process.env.NODE_ENV || 'development';
    // For KV v2, path is: mountPath/data/prefix/env/name
    return `${this.mountPath}/data/${this.prefix}/${env}/${name}`;
  }

  /**
   * Test connection to Vault
   */
  async testConnection() {
    try {
      // Check if authenticated
      const health = await this.client.health();

      if (!health.initialized) {
        throw new Error('Vault is not initialized');
      }

      if (health.sealed) {
        throw new Error('Vault is sealed');
      }

      // Verify token is valid
      await this.client.tokenLookupSelf();

      return true;
    } catch (error) {
      console.error('[VAULT] Connection test failed:', error.message);
      throw error;
    }
  }

  /**
   * Renew a lease
   */
  async renewLease(leaseId, increment = null) {
    try {
      const response = await this.client.write('sys/leases/renew', {
        lease_id: leaseId,
        increment: increment,
      });

      return response;
    } catch (error) {
      console.error(`[VAULT] Failed to renew lease ${leaseId}:`, error.message);
      throw error;
    }
  }

  /**
   * Start background task to renew leases
   */
  startLeaseRenewal() {
    // Check every minute
    setInterval(async () => {
      for (const [name, lease] of this.leases.entries()) {
        if (!lease.renewable) continue;

        // Renew if less than 1 minute remaining
        const now = Date.now();
        const expiresAt = lease.created_at + (lease.lease_duration * 1000);
        const timeRemaining = expiresAt - now;

        if (timeRemaining < 60000) {
          try {
            console.log(`[VAULT] Renewing lease for ${name}`);
            const renewed = await this.renewLease(lease.lease_id);

            // Update lease info
            lease.lease_duration = renewed.lease_duration;
            lease.created_at = Date.now();
          } catch (error) {
            console.error(`[VAULT] Failed to renew lease for ${name}:`, error.message);

            // Try to fetch a new secret
            try {
              await this.getSecret(name);
            } catch (refetchError) {
              console.error(`[VAULT] Failed to refetch secret ${name}:`, refetchError.message);
            }
          }
        }
      }
    }, 60000); // Check every minute
  }

  /**
   * Enable audit logging
   */
  async enableAudit(path = 'file', options = {}) {
    try {
      await this.client.write(`sys/audit/${path}`, {
        type: 'file',
        options: {
          file_path: options.file_path || '/var/log/vault-audit.log',
          ...options,
        },
      });

      console.log(`[VAULT] Enabled audit logging at ${path}`);
    } catch (error) {
      console.error('[VAULT] Failed to enable audit:', error.message);
      throw error;
    }
  }

  /**
   * Create a database role for dynamic secrets
   */
  async createDatabaseRole(name, config) {
    try {
      await this.client.write(`database/roles/${name}`, config);
      console.log(`[VAULT] Created database role: ${name}`);
    } catch (error) {
      console.error('[VAULT] Failed to create database role:', error.message);
      throw error;
    }
  }

  /**
   * Generate dynamic database credentials
   */
  async getDynamicDBCredentials(roleName) {
    try {
      const response = await this.client.read(`database/creds/${roleName}`);

      return {
        username: response.data.username,
        password: response.data.password,
        lease_id: response.lease_id,
        lease_duration: response.lease_duration,
      };
    } catch (error) {
      console.error('[VAULT] Failed to generate dynamic credentials:', error.message);
      throw error;
    }
  }
}

// Export singleton
let instance = null;

function getVaultSecretsProvider(options = {}) {
  if (!instance) {
    instance = new VaultSecretsProvider(options);
  }
  return instance;
}

module.exports = getVaultSecretsProvider();
module.exports.VaultSecretsProvider = VaultSecretsProvider;
module.exports.getVaultSecretsProvider = getVaultSecretsProvider;

/**
 * Secured Express Application with Proper Secrets Management
 * 
 * SECURITY IMPROVEMENTS:
 * - Uses secrets manager (AWS/Azure/Vault) or secure .env loading
 * - Validates secrets on startup (fail-secure)
 * - No hardcoded secrets or weak defaults
 * - Comprehensive security controls (OWASP Top 10)
 */

// ============================================
// STEP 1: INITIALIZE SECRETS FIRST
// ============================================
// This must be done BEFORE any other imports that might need secrets

const { initializeSecrets, getSecretsManager } = require('./config/secrets');

// Initialize secrets manager (async IIFE)
(async () => {
  try {
    // Initialize secrets manager
    // Will use AWS/Azure/Vault in production, .env in development
    await initializeSecrets({
      provider: process.env.SECRETS_PROVIDER || 'env', // 'aws', 'azure', 'vault', or 'env'
      cacheTTL: 300000, // 5 minutes
      auditLog: true,
    });

    console.log('[APP] Secrets manager initialized successfully');

    // Start the application
    await startApplication();
  } catch (error) {
    console.error('[APP] FATAL: Failed to initialize application:', error.message);
    process.exit(1); // Fail-secure
  }
})();

/**
 * Start the Express application
 */
async function startApplication() {
  const express = require('express');
  const helmet = require('helmet');
  const rateLimit = require('express-rate-limit');
  const cors = require('cors');
  const morgan = require('morgan');
  const { body, query, validationResult } = require('express-validator');
  const jwt = require('jsonwebtoken');
  const bcrypt = require('bcrypt');

  const app = express();
  const secretsManager = getSecretsManager();

  // ============================================
  // LOAD CONFIGURATION FROM SECRETS
  // ============================================
  const JWT_SECRET = await secretsManager.getSecret('JWT_SECRET', { required: true });
  const JWT_EXPIRES_IN = await secretsManager.getSecret('JWT_EXPIRES_IN') || '1h';
  const SESSION_SECRET = await secretsManager.getSecret('SESSION_SECRET', { required: true });
  const PORT = await secretsManager.getSecret('PORT') || 3000;
  const NODE_ENV = process.env.NODE_ENV || 'development';

  // Load CORS whitelist from secrets or config
  const ALLOWED_ORIGINS = (await secretsManager.getSecret('ALLOWED_ORIGINS') || 
    'https://yourdomain.com,https://app.yourdomain.com').split(',');

  console.log(`[APP] Starting in ${NODE_ENV} mode`);

  // ============================================
  // SECURITY HEADERS (Helmet)
  // ============================================
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        scriptSrc: ["'self'"],
        imgSrc: ["'self'", "data:", "https:"],
      },
    },
    hsts: {
      maxAge: 31536000,
      includeSubDomains: true,
      preload: true
    },
    frameguard: {
      action: 'deny'
    },
    noSniff: true,
    xssFilter: true
  }));

  // ============================================
  // CORS CONFIGURATION
  // ============================================
  const corsOptions = {
    origin: function (origin, callback) {
      if (!origin || ALLOWED_ORIGINS.indexOf(origin) !== -1) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    credentials: true,
    optionsSuccessStatus: 200,
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization']
  };

  app.use(cors(corsOptions));

  // ============================================
  // REQUEST PARSING & SIZE LIMITS
  // ============================================
  app.use(express.json({ limit: '10kb' }));
  app.use(express.urlencoded({ extended: true, limit: '10kb' }));

  // ============================================
  // RATE LIMITING
  // ============================================
  const generalLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
  });

  const strictLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 20,
    message: 'Too many requests, please try again later.'
  });

  app.use('/api/', generalLimiter);

  // ============================================
  // LOGGING & MONITORING
  // ============================================
  morgan.token('user-id', (req) => req.user ? req.user.id : 'anonymous');

  app.use(morgan(':remote-addr :user-id :method :url :status :response-time ms', {
    stream: {
      write: (message) => {
        console.log(`[ACCESS] ${message.trim()}`);
      }
    }
  }));

  // ============================================
  // AUTHENTICATION MIDDLEWARE
  // ============================================
  const authenticateToken = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
      return res.status(401).json({ 
        error: 'Access denied. No token provided.' 
      });
    }

    try {
      const verified = jwt.verify(token, JWT_SECRET);
      req.user = verified;
      next();
    } catch (err) {
      console.error(`[SECURITY] Failed authentication from ${req.ip}`);
      return res.status(403).json({ 
        error: 'Invalid or expired token.' 
      });
    }
  };

  // ============================================
  // INPUT VALIDATION
  // ============================================
  const validate = (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid input',
        details: errors.array() 
      });
    }
    next();
  };

  // ============================================
  // ERROR HANDLING
  // ============================================
  const errorHandler = (err, req, res, next) => {
    console.error(`[ERROR] ${err.stack}`);

    const isDevelopment = NODE_ENV === 'development';

    res.status(err.status || 500).json({
      error: isDevelopment ? err.message : 'Internal server error',
      ...(isDevelopment && { stack: err.stack })
    });
  };

  // ============================================
  // ROUTES
  // ============================================

  // Health check with secrets validation
  app.get('/health', async (req, res) => {
    const secretsHealth = await secretsManager.healthCheck();

    res.json({ 
      status: 'ok',
      secrets: secretsHealth.healthy ? 'connected' : 'error',
    });
  });

  // Login endpoint
  app.post('/api/login', 
    strictLimiter,
    [
      body('email').isEmail().normalizeEmail(),
      body('password').isLength({ min: 8 }),
    ],
    validate,
    async (req, res, next) => {
      try {
        const { email, password } = req.body;

        // In production: Query database and use bcrypt
        // const user = await db.query('SELECT * FROM users WHERE email = $1', [email]);
        // const isValid = await bcrypt.compare(password, user.password_hash);

        // Demo only - replace with real authentication
        if (email === 'admin@example.com' && password === 'SecureP@ss123') {
          const token = jwt.sign(
            { id: 1, email: email, role: 'admin' },
            JWT_SECRET,
            { expiresIn: JWT_EXPIRES_IN }
          );

          res.json({ token, expiresIn: JWT_EXPIRES_IN });
        } else {
          res.status(401).json({ error: 'Invalid credentials' });
        }
      } catch (error) {
        next(error);
      }
    }
  );

  // Protected users endpoint
  app.get('/api/users', 
    authenticateToken,
    [
      query('page').optional().isInt({ min: 1 }),
      query('limit').optional().isInt({ min: 1, max: 100 }),
    ],
    validate,
    (req, res, next) => {
      try {
        console.log(`[AUDIT] User ${req.user.id} accessed /api/users`);

        const page = parseInt(req.query.page) || 1;
        const limit = parseInt(req.query.limit) || 10;

        const users = [
          { id: 1, name: 'Alice', email: 'alice@example.com' },
          { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        const sanitizedUsers = users.map(user => {
          if (req.user.role === 'admin') {
            return user;
          } else {
            return { id: user.id, name: user.name };
          }
        });

        res.json({
          data: sanitizedUsers,
          pagination: { page, limit, total: users.length }
        });
      } catch (error) {
        next(error);
      }
    }
  );

  // Protected user detail endpoint
  app.get('/api/users/:id',
    authenticateToken,
    validate,
    (req, res, next) => {
      try {
        const userId = parseInt(req.params.id);

        if (isNaN(userId)) {
          return res.status(400).json({ error: 'Invalid user ID' });
        }

        if (req.user.role !== 'admin' && req.user.id !== userId) {
          console.warn(`[SECURITY] Unauthorized access attempt by user ${req.user.id}`);
          return res.status(403).json({ 
            error: 'Access denied. Insufficient permissions.' 
          });
        }

        const users = {
          1: { id: 1, name: 'Alice', email: 'alice@example.com' },
          2: { id: 2, name: 'Bob', email: 'bob@example.com' },
        };

        const user = users[userId];

        if (!user) {
          return res.status(404).json({ error: 'User not found' });
        }

        res.json({ data: user });
      } catch (error) {
        next(error);
      }
    }
  );

  // Secrets rotation endpoint (admin only)
  app.post('/api/admin/secrets/rotate',
    authenticateToken,
    async (req, res, next) => {
      try {
        if (req.user.role !== 'admin') {
          return res.status(403).json({ error: 'Admin access required' });
        }

        console.log(`[SECURITY] Secret rotation triggered by user ${req.user.id}`);

        // Clear secret cache to force reload
        secretsManager.clearCache();

        res.json({ 
          message: 'Secret cache cleared. New secrets will be loaded on next access.',
          timestamp: new Date().toISOString()
        });
      } catch (error) {
        next(error);
      }
    }
  );

  // 404 handler
  app.use((req, res) => {
    res.status(404).json({ error: 'Endpoint not found' });
  });

  // Error handler
  app.use(errorHandler);

  // ============================================
  // START SERVER
  // ============================================
  const server = app.listen(PORT, () => {
    console.log(`[APP] Server running on port ${PORT}`);
    console.log(`[APP] Environment: ${NODE_ENV}`);
    console.log(`[APP] Secrets provider: ${process.env.SECRETS_PROVIDER || 'env'}`);
    console.log('[APP] ✓ All security controls active');
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('[APP] SIGTERM received, shutting down gracefully...');
    server.close(() => {
      console.log('[APP] Server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('[APP] SIGINT received, shutting down gracefully...');
    server.close(() => {
      console.log('[APP] Server closed');
      process.exit(0);
    });
  });

  return server;
}

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('[APP] Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = startApplication;
